globalThis.DEClic_BUILTINS = [{"id": "marketing", "title": "Marketing", "description": "Définitions et notions essentielles du marketing.", "symbol": "M", "storageKey": "declic-marketing-concepts-v3", "cards": [{"id": "marketing-concept-001", "chapter": "Bases du marketing", "question": "Quelle est la définition du marketing ?", "answer": "Le marketing regroupe les activités qui permettent de comprendre les besoins et désirs, de concevoir une offre adaptée et de créer, communiquer et délivrer de la valeur. Il vise des relations durables avec les clients.", "sources": [{"documentId": "m1", "page": 11, "excerpt": "1-1) Des définitions\nde nombreuses définitions…\n•\nKotler : « C’est satisfaire les besoins et les désirs des\nconsommateurs mieux que le concurrent. »\n•\nSelon l’Association Française du Marketing (AFM) :\nLe concept de marketing est « une vision spécifique des\néchanges. Ceux-ci doivent être équitables et impliquer la\ncréation de valeur pour chacune des parties prenantes\n(individus, organisations, institutions). »\n•", "highlight": "définition"}]}, {"id": "marketing-concept-002", "chapter": "Bases du marketing", "question": "Qu’est-ce qu’un besoin ?", "answer": "Un besoin est un état de manque lié à la nature humaine. Il peut être physique, social ou individuel.", "sources": [{"documentId": "m1", "page": 17, "excerpt": "marché et les besoins des consommateurs\n2- Le marketing pour comprendre le marché et \nles besoins des consommateurs\n2-1)Besoins, désirs et demande\nBesoins\n⇒Etat personnel de manque (liés\ndirectement à la nature humaine)\n• Besoins\nphysiques\n(manger,\nse\nloger, se chauffer…)\n• Besoins\nsociaux\n(appartenance,\naffection…)\n• Besoins individuels (connaissance,\nexpression de soi…)\nDésirs\n⇒\nForme\nque\nprennent les besoins\nsous\nl’effet\nde\nla\nculture\net\nde", "highlight": "besoins"}]}, {"id": "marketing-concept-003", "chapter": "Bases du marketing", "question": "Qu’est-ce qu’un désir ?", "answer": "Un désir est la forme précise que prend un besoin sous l’influence de la culture et de la personnalité.", "sources": [{"documentId": "m1", "page": 17, "excerpt": "2-1)Besoins, désirs et demande\nBesoins\n⇒Etat personnel de manque (liés\ndirectement à la nature humaine)\n• Besoins\nphysiques\n(manger,\nse\nloger, se chauffer…)\n• Besoins\nsociaux\n(appartenance,\naffection…)\n• Besoins individuels (connaissance,\nexpression de soi…)\nDésirs\n⇒\nForme\nque\nprennent les besoins\nsous\nl’effet\nde\nla\nculture\net\nde\nla\npersonnalité\nindividuelle\nDemande\n⇒quantité de produits\nou\nservices\nque\nles\nconsommateurs\nsont\nprêts\net\ncapable", "highlight": "désirs"}]}, {"id": "marketing-concept-004", "chapter": "Bases du marketing", "question": "Qu’est-ce que la demande ?", "answer": "La demande correspond aux produits ou services que les consommateurs veulent et peuvent acheter, à un prix donné et pendant une période donnée.", "sources": [{"documentId": "m1", "page": 17, "excerpt": "2-1)Besoins, désirs et demande\nBesoins\n⇒Etat personnel de manque (liés\ndirectement à la nature humaine)\n• Besoins\nphysiques\n(manger,\nse\nloger, se chauffer…)\n• Besoins\nsociaux\n(appartenance,\naffection…)\n• Besoins individuels (connaissance,\nexpression de soi…)\nDésirs\n⇒\nForme\nque\nprennent les besoins\nsous\nl’effet\nde\nla\nculture\net\nde\nla\npersonnalité\nindividuelle\nDemande\n⇒quantité de produits\nou\nservices\nque\nles\nconsommateurs\nsont\nprêts\net\ncapable", "highlight": "demande"}]}, {"id": "marketing-concept-005", "chapter": "Bases du marketing", "question": "Quelle différence y a-t-il entre besoin, désir et demande ?", "answer": "Le besoin est un manque. Le désir est la réponse précise souhaitée. La demande suppose une volonté d’achat et un pouvoir d’achat suffisant.", "sources": [{"documentId": "m1", "page": 19, "excerpt": "pouvoir d’achat\nEn fonction des désirs et d’un \npouvoir d’achat suffisant, la \ndemande se crée\n2- Le marketing pour comprendre le marché et \nles besoins des consommateurs\n2-1)Besoins, désirs et demande\n2- Le marketing pour comprendre le marché et \nles besoins des consommateurs \n2-1)Besoins, désirs et demande\n⇒En marketing, les organisations font des efforts pour \ncomprendre les besoins, les désirs et la demande des clients", "highlight": "pouvoir"}]}, {"id": "marketing-concept-006", "chapter": "Bases du marketing", "question": "Quels sont les cinq niveaux de besoins de Maslow ?", "answer": "Besoins physiologiques, sécurité, appartenance, estime et accomplissement de soi.", "sources": [{"documentId": "m1", "page": 18, "excerpt": "La pyramide des besoins humains de Maslow\nMANGER\n=\nbesoin\nMANGER UN MAGNUM\n=\ndésir\nLe besoin se transforme en désir dès lors qu’il \nporte sur un produit spécifique\nLes désirs sont souvent \nfaçonnés par la société et \npar d’autres facteurs (cf \nséquence sur le comportement des \nconsommateurs)\n⇒repas français VS japonais\n2- Le marketing pour comprendre le marché et \nles besoins des consommateurs", "highlight": "Maslow"}]}, {"id": "marketing-concept-007", "chapter": "Bases du marketing", "question": "Quels sont les cinq types de besoins distingués par Kotler ?", "answer": "Besoins exprimés, réels, latents, rêvés et profonds. Ils correspondent à ce que le client dit, veut dire, n’envisage pas encore, rêve d’obtenir ou recherche plus secrètement.", "sources": [{"documentId": "m1", "page": 18, "excerpt": "1- Les besoins exprimés (ce que dit le client)\n2- Les besoins réels (ce qu’il veut dire)\n3- Les besoins latents (ce à quoi il ne pense pas)\n4- Les besoins rêvés (ce sont il rêverait)\n5- Les besoins profonds (ce qui le motive \nsecrètement)\n2- Le marketing pour comprendre le marché et \nles besoins des consommateurs\n2-1)Besoins, désirs et demande\nGénéralement, on ne peut satisfaire qu’un besoin d’un certain", "highlight": "exprimés"}]}, {"id": "marketing-concept-008", "chapter": "Bases du marketing", "question": "Qu’est-ce qu’une offre commerciale ?", "answer": "C’est un bien ou un service proposé sur un marché pour satisfaire un besoin ou un désir.", "sources": [{"documentId": "m1", "page": 20, "excerpt": "2-2) L’offre commerciale\n⇒Offre : Produit ou service proposés pour satisfaire un besoin ou un désir sur un\nmarché donné = réponse à un besoin\n• L’offre\ncommerciale\nn’est\ngénéralement\nque\nl’une\ndes\npossibilités\nqu’a\nun\nconsommateur de satisfaire un besoin : une multitude d’offres est à sa disposition\n• Un besoin présente une pérennité alors que tous les produits/services sont\namenés à terme à disparaître ou à évoluer significativement", "highlight": "offre"}]}, {"id": "marketing-concept-009", "chapter": "Bases du marketing", "question": "Quelle est la différence entre un bien et un service ?", "answer": "Un bien est tangible, alors qu’un service est intangible.", "sources": [{"documentId": "m1", "page": 8, "excerpt": "tangible\ne.g. voiture, café, \nlivre\nintangible\ne.g. livraison, coupe \ncoiffeur\n• C’est le cas des entreprises qui vendent des produits ou\ndes services, mais la notion de marketing a été étendue à\nd’autres\nactivités\n(e.g.\nles\nassociations\nhumanitaires,\nsportives, …)\n• Nous parlerons donc d’organisations\nIntroduction\n• Le marketing cherche à produire des relations durables et\n« rentables » avec les clients/prospects :\n\nattirer\nde\nnouveaux", "highlight": "tangible"}]}, {"id": "marketing-concept-010", "chapter": "Bases du marketing", "question": "Qu’est-ce que la myopie marketing ?", "answer": "C’est le fait de se concentrer sur le produit lui-même plutôt que sur les besoins, bénéfices ou expériences recherchés par les clients.", "sources": [{"documentId": "m1", "page": 20, "excerpt": "Marketing myopia : s’attacher davantage au produit ou service lui-même \nplutôt qu’aux bénéfices ou aux expériences produites (voir un film au \ncinéma n’est pas simplement voir un film)", "highlight": "myopia"}]}, {"id": "marketing-concept-011", "chapter": "Bases du marketing", "question": "Qu’est-ce que la valeur perçue ?", "answer": "C’est la différence entre les bénéfices perçus et les coûts perçus par le client. Elle est subjective.", "sources": [{"documentId": "m1", "page": 11, "excerpt": "les bénéfices attendus et les coûts \ntangibles et intangibles perçus par le \nclient) et de relation avec le client\n• Ministère de l’Économie et des Finances : « La\nmercatique consiste en l’ensemble des actions\nqui, dans une économie de marché, ont pour\nobjectif de prévoir ou de constater et, le cas\néchéant, de stimuler, susciter ou renouveler les\nbesoins\ndu\nconsommateur\net\nde\nréaliser\nl’adaptation continue de l’appareil productif et", "highlight": "bénéfices"}]}, {"id": "marketing-concept-012", "chapter": "Bases du marketing", "question": "Qu’est-ce que la satisfaction du client ?", "answer": "Elle résulte de la comparaison entre les attentes du client et l’expérience qu’il a réellement vécue.", "sources": [{"documentId": "m1", "page": 22, "excerpt": "Valeur et satisfaction client\n•\nLa valeur d’un bien/service est propre à chaque individu et vaut ce que celui-ci est prêt à donner \nou payer pour l’obtenir\n•\nLe sentiment de satisfaction résulte de l’écart entre les attentes et l’expérience vécue\n•\nPromettre trop risque d’insatisfaction\n•\nPromettre peu n’attire pas de nouveaux consommateurs\n• Généralement, les consommateurs satisfaits achètent à nouveau et promeuvent  l’offre", "highlight": "satisfaction"}]}, {"id": "marketing-concept-013", "chapter": "Bases du marketing", "question": "Quelle est la différence entre un client et un prospect ?", "answer": "Un client a déjà acheté. Un prospect est un client potentiel qui n’a pas encore acheté.", "sources": [{"documentId": "m1", "page": 8, "excerpt": "« rentables » avec les clients/prospects :\n\nattirer\nde\nnouveaux\nclients/prospects\npar\nune\n« promesse de valeur » et conserver la clientèle existante\npar divers moyens\nsatisfaire les besoins\ncréer de la valeur pour obtenir des parts de marchés,\ndes marges et donc pour survivre ou prospérer\nUn client a déjà acheté vos \nproduits ou services. Un \nprospect, en revanche, est un \npotentiel client qui n'a pas \nencore acheté.", "highlight": "prospect"}]}, {"id": "marketing-concept-014", "chapter": "Bases du marketing", "question": "Que signifient B2C, B2B et C2C ?", "answer": "B2C : entreprise vers consommateur. B2B : entreprise vers entreprise. C2C : échanges entre consommateurs.", "sources": [{"documentId": "m1", "page": 14, "excerpt": "Marketing B2C (business to consumer)\nMarketing B2B (business to business)\nMarketing C2C (consumer to consumer)\nLa nature de l’offre\nProduits\nServices\nCanal de communication\nTraditionnel", "highlight": "B2C"}]}, {"id": "marketing-concept-015", "chapter": "Démarche et orientations", "question": "Quelles sont les trois phases de la démarche marketing ?", "answer": "Le marketing d’études, le marketing stratégique et le marketing opérationnel. Le contrôle permet de mesurer les résultats et de corriger les actions.", "sources": [{"documentId": "m1", "page": 25, "excerpt": "lancement sur le marché ou piloter les phases du cycle de vie\n• Elle s’organise autour des « 4P » du marketing mix (produit-prix-distribution-promotion)\n3- Le marketing \nopérationnel", "highlight": "phases"}]}, {"id": "marketing-concept-016", "chapter": "Démarche et orientations", "question": "Qu’est-ce que le marketing d’études ?", "answer": "Il consiste à recueillir et analyser des informations sur le marché, l’entreprise et son environnement pour comprendre la situation.", "sources": [{"documentId": "m1", "page": 25, "excerpt": "1- Le marketing d’études\n• Sélectionner les segments que l’entreprise souhaite cibler sur un marché donné et à élaborer \nl’offre la plus adaptée (stratégie SCP)\n• Phase limitée si l’entreprise adopte un marketing de masse indifférencié \n2- Le marketing stratégique\n• Mettre en œuvre des actions marketing une fois le produit élaboré, pour accompagner son \nlancement sur le marché ou piloter les phases du cycle de vie", "highlight": "études"}]}, {"id": "marketing-concept-017", "chapter": "Démarche et orientations", "question": "Qu’est-ce que le marketing stratégique ?", "answer": "Il consiste notamment à choisir les segments à servir et à définir une offre et un positionnement adaptés.", "sources": [{"documentId": "m1", "page": 25, "excerpt": "2- Le marketing stratégique\n• Mettre en œuvre des actions marketing une fois le produit élaboré, pour accompagner son \nlancement sur le marché ou piloter les phases du cycle de vie\n• Elle s’organise autour des « 4P » du marketing mix (produit-prix-distribution-promotion)\n3- Le marketing \nopérationnel", "highlight": "stratégique"}]}, {"id": "marketing-concept-018", "chapter": "Démarche et orientations", "question": "Qu’est-ce que le marketing opérationnel ?", "answer": "Il met en œuvre les actions marketing autour du produit, du prix, de la distribution et de la communication.", "sources": [{"documentId": "m1", "page": 25, "excerpt": "opérationnel\n3 phases au sein d’une démarche itérative", "highlight": "opérationnel"}]}, {"id": "marketing-concept-019", "chapter": "Démarche et orientations", "question": "Qu’est-ce qu’une étude documentaire ?", "answer": "C’est l’exploitation d’informations déjà disponibles. Elle est rapide et peu coûteuse, mais les données peuvent être trop générales ou peu adaptées.", "sources": [{"documentId": "m1", "page": 26, "excerpt": "Etude documentaire : documents déjà existants, données disponibles \n(Ex : Insee, enquêtes d’instituts de sondage, …)\n•\nAvantages : faible coût, rapide\n•\nInconvénients : fiabilités, manque de précision , informations globales, …\n•\nEnquêtes : collecter soi-même les infos sur le terrain \n•\nAvantages : précision, gestion de objectifs\n•\nInconvénients : temps, coût élevé\nDifférents types d’enquêtes\n-\nObservations\n-\nSondages (quantitative)\n-", "highlight": "documentaire"}]}, {"id": "marketing-concept-020", "chapter": "Démarche et orientations", "question": "Quelle différence y a-t-il entre une étude qualitative et une étude quantitative ?", "answer": "L’étude qualitative cherche à comprendre les motivations, notamment par des entretiens. L’étude quantitative mesure des phénomènes, notamment par des sondages.", "sources": [{"documentId": "m1", "page": 26, "excerpt": "Entretiens (qualitatif)", "highlight": "qualitatif"}]}, {"id": "marketing-concept-021", "chapter": "Démarche et orientations", "question": "Qu’est-ce que l’orientation production ?", "answer": "Elle donne la priorité à la capacité de production, à la productivité, à la baisse des coûts et à la disponibilité des produits.", "sources": [{"documentId": "m1", "page": 30, "excerpt": "5-1) L’orientation production\nLe marketing a un rôle limité et passif : organiser l'écoulement des\nproduits fabriqués.\nLes préoccupations prioritaires sont de :\n• développer la capacité de production,\n• trouver les financements nécessaires à ce développement,\n• réduire les coûts en allongeant les séries,\n• améliorer la productivité en rationalisant les méthodes d'organisation du\ntravail\nConception\nProduction\nDiffusion\nConsommation", "highlight": "production"}]}, {"id": "marketing-concept-022", "chapter": "Démarche et orientations", "question": "Qu’est-ce que l’orientation produit ?", "answer": "Elle repose sur l’idée que le consommateur choisit le produit offrant la meilleure qualité ou les meilleures performances techniques.", "sources": [{"documentId": "m1", "page": 30, "excerpt": "produits fabriqués.\nLes préoccupations prioritaires sont de :\n• développer la capacité de production,\n• trouver les financements nécessaires à ce développement,\n• réduire les coûts en allongeant les séries,\n• améliorer la productivité en rationalisant les méthodes d'organisation du\ntravail\nConception\nProduction\nDiffusion\nConsommation\n5- Les orientations marketing\n5-2) L’orientation produit\n•", "highlight": "produit"}]}, {"id": "marketing-concept-023", "chapter": "Démarche et orientations", "question": "Qu’est-ce que l’orientation vente ?", "answer": "Elle consiste à chercher à faire accepter et acheter ce qui a été produit, grâce à la pression commerciale et publicitaire.", "sources": [{"documentId": "m1", "page": 31, "excerpt": "5-3) L’orientation vente\n•\nTenter de forcer le marché à accepter ce qui a été produit (rôle prédominent du\nvendeur et de la publicité)\n•\nLa prééminence de l'optique « vente » est encore manifeste dans certains secteurs\n(énergie, téléphonie, crédit à la consommation…)\nLes abus génèrent des contre-pouvoirs (mouvement consumériste) et des\nmesures législatives (e.g. bloctel)\nConception\nProduction\nPression \ncommerciale\nConsommation", "highlight": "vente"}]}, {"id": "marketing-concept-024", "chapter": "Démarche et orientations", "question": "Qu’est-ce que l’orientation marketing ?", "answer": "Elle part des besoins et attentes des consommateurs pour concevoir les produits et services susceptibles de les satisfaire.", "sources": [{"documentId": "m1", "page": 32, "excerpt": "semble plus judicieux d’étudier ces derniers pour connaître leurs besoins et \nproduire des biens en conséquence\nConception du \nproduit/service\nProduction\nConsommateur/prospects \n(besoins, attentes, \ndésirs…)\nMise sur le \nmarché\n5- Les orientations marketing\n5-4) L’orientation marketing\n•\nLe marketing se doit toute à la fois de guider le marché et de se laisser \nguider par le marché  : un mélange de technology push et de demand pull", "highlight": "besoins"}]}, {"id": "marketing-concept-025", "chapter": "Démarche et orientations", "question": "Qu’est-ce que le marketing sociétal ?", "answer": "Il recherche un équilibre entre les désirs des consommateurs, les objectifs de l’entreprise et le bien-être collectif à long terme.", "sources": [{"documentId": "m1", "page": 33, "excerpt": "5-5) L’orientation marketing sociétal\nNaît d’une question : en comblant les désirs immédiats des\nconsommateurs, le marketing ne menace-t-il pas son bien-être\nà long terme ?\nImpact de ma consommation sur ma santé, sur les autres…\nhttps://www.lemonde.fr/planete/article/2012/05/09/le-7e-continent-de-plastique-ces-tourbillons-de-\ndechets-dans-les-oceans_1696072_3244.html\n5- Les orientations marketing\n5-5) L’orientation marketing sociétal", "highlight": "sociétal"}]}, {"id": "marketing-concept-026", "chapter": "Environnement", "question": "Qu’est-ce que le macro-environnement ?", "answer": "C’est l’ensemble des grandes forces externes que l’organisation ne contrôle pas directement mais auxquelles elle doit s’adapter.", "sources": [{"documentId": "m2", "page": 4, "excerpt": "Le Macro-\nenvironnement\nLes fournisseurs\nLes concurrents\nLes acheteurs et les \nconsommateurs\nLes intermédiaires\nLes groupes \nd’influence\nL’environnem\nent \ntechnologique\nL’environnement politico-légal\nL’environnem\nent naturel\nL’environnem\nent socio-\nculturel\nL’environnement économique\nLes prescripteurs\nL’organisation\nL’environnement \ntechnologique\nL’environnement politico-\nlégal\nL’environnement \nnaturel\nL’environnement \nsocio-culturel", "highlight": "Macro"}]}, {"id": "marketing-concept-027", "chapter": "Environnement", "question": "Qu’est-ce que le micro-environnement ?", "answer": "Il est constitué des acteurs proches avec lesquels l’organisation interagit pour mener sa stratégie marketing.", "sources": [{"documentId": "m2", "page": 11, "excerpt": "→Le micro-environnement est constitué d’entités ou d’acteurs avec lesquels\nl’organisation doit interagir pour mener à bien sa stratégie marketing\n→Ceux-ci sont susceptibles d’affecter dans un sens positif ou négatif\nL’organisation\nLes fournisseurs\nLes concurrents\nLes acheteurs et les\nconsommateurs\nLes intermédiaires\nLes groupes \nd’influence\nLes prescripteurs\n1- L’environnement marketing externe\n1-2) Le micro-environnement", "highlight": "micro"}]}, {"id": "marketing-concept-028", "chapter": "Environnement", "question": "Que signifie PESTEL ?", "answer": "Politique, économique, socioculturel, technologique, écologique et légal. Cet outil sert à analyser le macro-environnement.", "sources": [{"documentId": "m2", "page": 5, "excerpt": "• L’acronyme PESTEL est un moyen mémotechnique pour retenir les éléments\nconstitutifs\ndu\nmacro-environnement\n:\npolitique\n–\néconomique\n–\nsocial\n–\ntechnologique – légal – environnemental\nModèle PESTEL : répartit les influences environnementales en six grandes\ncatégories : politiques, économiques, sociologiques, technologiques, écologiques\net légales.\n• On peut établir des scénarios sur la manière dont\nla stratégie doit évoluer en", "highlight": "PESTEL"}]}, {"id": "marketing-concept-029", "chapter": "Environnement", "question": "Quels sont les principaux acteurs du micro-environnement ?", "answer": "Les acheteurs et consommateurs, les fournisseurs, les concurrents, les prescripteurs, les intermédiaires et les groupes d’influence.", "sources": [{"documentId": "m2", "page": 11, "excerpt": "Les fournisseurs\nLes concurrents\nLes acheteurs et les\nconsommateurs\nLes intermédiaires\nLes groupes \nd’influence\nLes prescripteurs\n1- L’environnement marketing externe\n1-2) Le micro-environnement\nAcheteurs = individus qui achètent les produits/services d’une entreprise \n≠\nConsommateurs = individus qui consomment les produits/services d’une entreprise\n•\nIl est primordial pour l’organisation de bien connaître ses clients (ou clients", "highlight": "fournisseurs"}]}, {"id": "marketing-concept-030", "chapter": "Environnement", "question": "Quelle différence y a-t-il entre un acheteur et un consommateur ?", "answer": "L’acheteur effectue l’achat ; le consommateur utilise le produit ou le service. Ce peut être la même personne ou deux personnes différentes.", "sources": [{"documentId": "m2", "page": 11, "excerpt": "Les acheteurs et les\nconsommateurs\nLes intermédiaires\nLes groupes \nd’influence\nLes prescripteurs\n1- L’environnement marketing externe\n1-2) Le micro-environnement\nAcheteurs = individus qui achètent les produits/services d’une entreprise \n≠\nConsommateurs = individus qui consomment les produits/services d’une entreprise\n•\nIl est primordial pour l’organisation de bien connaître ses clients (ou clients", "highlight": "acheteurs"}]}, {"id": "marketing-concept-031", "chapter": "Environnement", "question": "Qu’est-ce qu’un prescripteur ?", "answer": "C’est une personne ou une organisation qui influence la décision d’achat par ses conseils ou recommandations, sans nécessairement acheter.", "sources": [{"documentId": "m2", "page": 18, "excerpt": "Prescripteurs = individus ou organisations qui influencent les décisions d’achat des consommateurs\nsans nécessairement effectuer eux-mêmes l’achat par le biais de conseils, recommandations, …\n•\nDifférents types de prescripteurs\n•\nCercle familiale ou amis\n•\nProfessionnels de santé (recommandation de médicaments)\n•\nExperts techniques\n•\nInfluenceurs (blog, vidéos, …)\n•\nLeaders d’opinion\n•\nDistributeurs (par le biais de techniques commerciales)", "highlight": "Prescripteurs"}]}, {"id": "marketing-concept-032", "chapter": "Environnement", "question": "Quelle différence y a-t-il entre concurrence directe et indirecte ?", "answer": "La concurrence directe propose des produits ou services identiques ou très proches. La concurrence indirecte propose des solutions différentes répondant au même besoin.", "sources": [{"documentId": "m2", "page": 15, "excerpt": "Différents types de concurrents (directs, indirects)\nConcurrents directs : organisation offrant des produits/services \nidentiques ou très similaires. Coca-Cola versus Pepsi\nConcurrents indirects : organisation proposant des solutions \nalternatives qui répondent aux mêmes besoin du client. Cinéma \nversus Netflix versus Théâtre\n1- L’environnement marketing externe\n1-2) Le micro-environnement\nLes structures de marché existantes\nNombre", "highlight": "directs"}]}, {"id": "marketing-concept-033", "chapter": "Environnement", "question": "Qu’est-ce qu’un monopole ?", "answer": "C’est une structure de marché dans laquelle une seule entreprise propose l’offre considérée.", "sources": [{"documentId": "m2", "page": 15, "excerpt": "Monopole \nOligopole\nConcurrence \nmonopolistique\nEau\nElectricité\nTéléphonie\nLessive\nLivre\nJus de fruit, meuble\nBeaucoup\nUne seule\nQuelques unes\n1- L’environnement marketing externe", "highlight": "Monopole"}]}, {"id": "marketing-concept-034", "chapter": "Environnement", "question": "Qu’est-ce qu’un oligopole ?", "answer": "C’est une structure de marché dans laquelle quelques entreprises se partagent l’offre.", "sources": [{"documentId": "m2", "page": 15, "excerpt": "Oligopole\nConcurrence \nmonopolistique\nEau\nElectricité\nTéléphonie\nLessive\nLivre\nJus de fruit, meuble\nBeaucoup\nUne seule\nQuelques unes\n1- L’environnement marketing externe", "highlight": "Oligopole"}]}, {"id": "marketing-concept-035", "chapter": "Environnement", "question": "Quelles sont les cinq forces de Porter ?", "answer": "La rivalité entre concurrents, la menace des nouveaux entrants, la menace des substituts, le pouvoir de négociation des fournisseurs et le pouvoir de négociation des clients.", "sources": [{"documentId": "m2", "page": 17, "excerpt": "Les forces concurrentielles : le modèle de Porter\nConcurrents du \nsecteur\nRivalité existante entre \nles organisations\nEntrants potentiels\nSubstituts\nFournisseurs\nClients\nMenace de nouveaux entrants\nMenace de produits/services substituables\nPouvoir de négociation des clients\nPouvoir de négociation des fournisseurs\n1- L’environnement marketing externe\n1-2) Le micro-environnement\nLes forces concurrentielles : le modèle des 5 forces de Porter", "highlight": "Porter"}]}, {"id": "marketing-concept-036", "chapter": "Environnement", "question": "Qu’est-ce qu’une tendance de marché ?", "answer": "C’est une évolution durable des comportements, attentes ou technologies qui influence l’offre et la demande.", "sources": [{"documentId": "m2", "page": 23, "excerpt": "Qu’est-ce qu’une tendance de marché ?\n•\nÉvolutions durables des comportements, des attentes ou des technologies qui influencent\nl’offre et la demande\n•\nElles structurent l’environnement externe et guident les décisions stratégiques\nPourquoi les analyser ?\n•\nIdentifier les opportunités (nouveaux segments, innovations, …)\n•\nDétecter les menaces (concurrence accrue, obsolescence, …)\n•", "highlight": "tendance"}]}, {"id": "marketing-concept-037", "chapter": "Marché", "question": "Quelle est la définition d’un marché ?", "answer": "Un marché est le lieu de rencontre entre l’offre et la demande permettant des transactions. Il peut être physique ou virtuel.", "sources": [{"documentId": "m2", "page": 27, "excerpt": "Un marché = lieu de rencontre entre l’offre et la demande dans le but d’y opérer des\ntransactions (marché physique, virtuel, local, national, …)\n•\nSe définit d’un point de vue géographique, mais pas que !\n•\nIndispensable de le décrire selon le type de produit, la catégorie d’acheteur etc…\nE.g. marché des sneakers, marché français, marché des nourrissons, …\nUne organisation opère sur un ou plusieurs marchés en même temps\n2- Le marché", "highlight": "rencontre"}]}, {"id": "marketing-concept-038", "chapter": "Marché", "question": "Quelle différence y a-t-il entre un marché atomisé et un marché concentré ?", "answer": "Un marché atomisé est partagé entre de nombreux acteurs. Un marché concentré compte peu d’entreprises qui occupent une place importante.", "sources": [{"documentId": "m2", "page": 28, "excerpt": "• Marché fragmenté (ou atomisé) : de nombreux acteurs se partagent le marché\n• Marché concentré : peu d’entreprises sont présentes\n2- Le marché\n2-1) Qu’est-ce qu’un marché ?\nMarché des jus de fruits, \nmarché du lait, du textile, …\nMédia télévisé, téléphonie, \ntransport ferroviaire, …\nDeux approches : par l’offre ou par la demande \n2- Le marché\n2-2) Les différentes approches du marché\nOffre\nDemande\n1\n2\npoint de vue des produits qui", "highlight": "fragmenté"}]}, {"id": "marketing-concept-039", "chapter": "Marché", "question": "Qu’est-ce que le marché principal ?", "answer": "Il regroupe les produits techniquement identiques et directement concurrents.", "sources": [{"documentId": "m2", "page": 30, "excerpt": "Le marché principal : ensemble des produits techniquement identiques et directement\nconcurrents\n•\nLe marché environnant: produits substituts de nature différentes des produits du\nmarché principal, mais satisfaisant les mêmes besoins dans les mêmes conditions\n•\nLa marché générique : produits liés à la catégorie de besoins satisfaits par les produits\ndu marché principal\n•", "highlight": "principal"}]}, {"id": "marketing-concept-040", "chapter": "Marché", "question": "Qu’est-ce que le marché environnant ?", "answer": "Il regroupe les produits de nature différente qui peuvent se substituer aux produits du marché principal pour satisfaire le même besoin.", "sources": [{"documentId": "m2", "page": 30, "excerpt": "Le marché environnant: produits substituts de nature différentes des produits du\nmarché principal, mais satisfaisant les mêmes besoins dans les mêmes conditions\n•\nLa marché générique : produits liés à la catégorie de besoins satisfaits par les produits\ndu marché principal\n•\nLe marché support (ou marché des produits associés) : produits complémentaires\ndont l’existence est nécessaire à la consommation des produits des marché\nprécédents", "highlight": "environnant"}]}, {"id": "marketing-concept-041", "chapter": "Marché", "question": "Qu’est-ce que le marché générique ?", "answer": "Il regroupe les produits liés à la catégorie générale de besoins satisfaite par les produits du marché principal.", "sources": [{"documentId": "m2", "page": 30, "excerpt": "La marché générique : produits liés à la catégorie de besoins satisfaits par les produits\ndu marché principal\n•\nLe marché support (ou marché des produits associés) : produits complémentaires\ndont l’existence est nécessaire à la consommation des produits des marché\nprécédents\n2- Le marché\n2-2) Les différentes approches du marché", "highlight": "générique"}]}, {"id": "marketing-concept-042", "chapter": "Marché", "question": "Qu’est-ce que le marché support ?", "answer": "Il regroupe les produits associés ou complémentaires à la consommation des produits considérés.", "sources": [{"documentId": "m2", "page": 30, "excerpt": "Le marché support (ou marché des produits associés) : produits complémentaires\ndont l’existence est nécessaire à la consommation des produits des marché\nprécédents\n2- Le marché\n2-2) Les différentes approches du marché", "highlight": "support"}]}, {"id": "marketing-concept-043", "chapter": "Marché", "question": "Qu’est-ce que le marché réel ?", "answer": "Il correspond aux consommateurs qui ont acheté le produit pendant une période donnée.", "sources": [{"documentId": "m2", "page": 29, "excerpt": "Le marché actuel (ou réel) est constitué \ndes consommateurs (dits consommateurs \nactuels) ayant acheté au moins une fois un \nproduit considéré au cours d’une période \ndonnée. Le marché potentiel est constitué \ndes consommateurs actuels et des non-\nconsommateurs relatifs\n2\nDéfinit des segments de", "highlight": "actuel"}]}, {"id": "marketing-concept-044", "chapter": "Marché", "question": "Qu’est-ce que le marché potentiel ?", "answer": "Il rassemble les consommateurs actuels et les non-consommateurs relatifs.", "sources": [{"documentId": "m2", "page": 29, "excerpt": "donnée. Le marché potentiel est constitué \ndes consommateurs actuels et des non-\nconsommateurs relatifs\n2\nDéfinit des segments de", "highlight": "potentiel"}]}, {"id": "marketing-concept-045", "chapter": "Marché", "question": "Quelle différence y a-t-il entre un non-consommateur relatif et un non-consommateur absolu ?", "answer": "Le non-consommateur relatif pourrait devenir consommateur. Le non-consommateur absolu ne peut pas ou ne veut durablement pas consommer le produit dans le cadre étudié.", "sources": [{"documentId": "m2", "page": 30, "excerpt": "absolus\nNon consommateurs\nConsommateurs actuels\nMarché réel de l’entreprise\nProspects\nMarché potentiel\n2\nL’approche du marché par la demande\n2- Le marché\n2-2) Les différentes approches du marché\nL’approche par niveaux\n•\nLe marché principal : ensemble des produits techniquement identiques et directement\nconcurrents\n•\nLe marché environnant: produits substituts de nature différentes des produits du", "highlight": "absolus"}]}, {"id": "marketing-concept-046", "chapter": "Marché", "question": "Quelle différence y a-t-il entre un marché en volume et un marché en valeur ?", "answer": "Le volume mesure les quantités physiques vendues. La valeur mesure le montant monétaire des ventes.", "sources": [{"documentId": "m2", "page": 33, "excerpt": "volume\nvaleur\n= Nombre d’unités physiques du\nproduits achetés (tonne de riz,\nlitre de bière, …)\ne.g. en France, près de 3 kilos de \nchips sont vendus en moyenne \npar personne et par an\n= Sommes totales dépensées par\nles\nclients\npour\nle produit ou\nservice en question\ne.g. en France, le marché bio \nreprésente environ 12 millions \nd’euros en 2023 (Agence Bio)\n•\nCes\ndeux\nmesures\nsont\nnécessaires et complémentaires\n•\nParfois, seule le volume ou la", "highlight": "volume"}]}, {"id": "marketing-concept-047", "chapter": "Marché", "question": "Comment calcule-t-on le taux de croissance d’un marché ?", "answer": "Taux de croissance (%) = (valeur d’arrivée - valeur de départ) / valeur de départ × 100.", "sources": [{"documentId": "m2", "page": 33, "excerpt": "• Le taux de croissance d’un marché se calcule en volume ou en valeur\n• La part de marché absolue se calcule en volume ou en valeur :\n2- Le marché\n2-3) Les différentes mesures du marché\nTaux de croissance = (𝒕𝒂𝒊𝒍𝒍𝒆 𝒅𝒖 𝒎𝒂𝒓𝒄𝒉é 𝒆𝒏 𝑵ା𝟏) ି(𝒕𝒂𝒊𝒍𝒍𝒆 𝒅𝒖 𝒎𝒂𝒓𝒄𝒉é 𝒆𝒏 𝑵)\n𝒕𝒂𝒊𝒍𝒍𝒆 𝒅𝒖 𝒎𝒂𝒓𝒄𝒉é 𝒆𝒏 𝑵\nP𝐚𝐫𝐭 𝐝𝐞 𝐦𝐚𝐫𝐜𝐡é 𝒅ᇱ𝒖𝒏𝒆 𝒆𝒏𝒕𝒓𝒆𝒑𝒓𝒊𝒔𝒆= 𝒗𝒆𝒏𝒕𝒆𝒔 𝒅𝒆 𝒍ᇲ𝒆𝒏𝒕𝒓𝒆𝒑𝒓𝒊𝒔𝒆 \n𝑽𝒆𝒏𝒕𝒆𝒔 𝒅𝒖 𝒎𝒂𝒓𝒄𝒉é\n∗𝟏𝟎𝟎", "highlight": "croissance"}]}, {"id": "marketing-concept-048", "chapter": "Marché", "question": "Comment calcule-t-on une part de marché absolue ?", "answer": "Part de marché (%) = ventes de l’entreprise / ventes totales du marché × 100. Le calcul peut se faire en volume ou en valeur.", "sources": [{"documentId": "m2", "page": 33, "excerpt": "• La part de marché absolue se calcule en volume ou en valeur :\n2- Le marché\n2-3) Les différentes mesures du marché\nTaux de croissance = (𝒕𝒂𝒊𝒍𝒍𝒆 𝒅𝒖 𝒎𝒂𝒓𝒄𝒉é 𝒆𝒏 𝑵ା𝟏) ି(𝒕𝒂𝒊𝒍𝒍𝒆 𝒅𝒖 𝒎𝒂𝒓𝒄𝒉é 𝒆𝒏 𝑵)\n𝒕𝒂𝒊𝒍𝒍𝒆 𝒅𝒖 𝒎𝒂𝒓𝒄𝒉é 𝒆𝒏 𝑵\nP𝐚𝐫𝐭 𝐝𝐞 𝐦𝐚𝐫𝐜𝐡é 𝒅ᇱ𝒖𝒏𝒆 𝒆𝒏𝒕𝒓𝒆𝒑𝒓𝒊𝒔𝒆= 𝒗𝒆𝒏𝒕𝒆𝒔 𝒅𝒆 𝒍ᇲ𝒆𝒏𝒕𝒓𝒆𝒑𝒓𝒊𝒔𝒆 \n𝑽𝒆𝒏𝒕𝒆𝒔 𝒅𝒖 𝒎𝒂𝒓𝒄𝒉é\n∗𝟏𝟎𝟎\nEn analysant les parts de marché des concurrents présents, on peut identifier le leader, qui", "highlight": "absolue"}]}, {"id": "marketing-concept-049", "chapter": "Marché", "question": "Comment calcule-t-on une part de marché relative ?", "answer": "Part de marché relative = part de marché de l’entreprise / part de marché de son principal concurrent. C’est un ratio.", "sources": [{"documentId": "m2", "page": 34, "excerpt": "• La part de marché relative se calcule en volume ou en valeur :\n• La part de marché (PDM) relative indique la position concurrentielle sur un marché puisqu’elle\nmesure la distance entre une marque et le leader\n• Ainsi, une entreprise possédant une PDM relative de 1,1 domine certes le marché mais son\nchallenger vend presque autant\n• La part de marché absolus est un % tandis que la part de marché relative est un ratio\n2- Le marché", "highlight": "relative"}]}, {"id": "marketing-concept-050", "chapter": "Marché", "question": "Comment interprète-t-on une part de marché relative ?", "answer": "Supérieure à 1 : l’entreprise dépasse son principal concurrent. Égale à 1 : elles réalisent les mêmes ventes. Inférieure à 1 : l’entreprise est derrière.", "sources": [{"documentId": "m2", "page": 34, "excerpt": "• Ainsi, une entreprise possédant une PDM relative de 1,1 domine certes le marché mais son\nchallenger vend presque autant\n• La part de marché absolus est un % tandis que la part de marché relative est un ratio\n2- Le marché\n2-3) Les différentes mesures du marché\nPart de marché de l’entreprise= \n𝒑𝒂𝒓𝒕 𝒅𝒆 𝒎𝒂𝒓𝒄𝒉é 𝒂𝒃𝒔𝒐𝒍𝒖𝒆 𝒅𝒆 𝒍ᇲ𝒆𝒏𝒕𝒓𝒆𝒑𝒓𝒊𝒔𝒆 (𝒆𝒏 %)\n𝒑𝒂𝒓𝒕 𝒅𝒆 𝒎𝒂𝒓𝒄𝒉é 𝒂𝒃𝒔𝒐𝒍𝒖𝒆 𝒅𝒖 𝟏𝒆𝒓 𝒄𝒐𝒏𝒄𝒖𝒓𝒓𝒆𝒏𝒕 𝒅𝒆 𝒍ᇲ𝒆𝒏𝒕𝒓𝒆𝒑𝒓𝒊𝒔𝒆", "highlight": "1,1"}]}, {"id": "marketing-concept-051", "chapter": "Marché", "question": "Comment calcule-t-on le taux de pénétration ?", "answer": "Taux de pénétration (%) = marché réel / marché potentiel × 100.", "sources": [{"documentId": "m2", "page": 34, "excerpt": "Le taux de pénétration est le marché réel rapporté au marché potentiel. Un taux de\npénétration bas signifie qu’il existe un potentiel de croissance élevé pour toutes les\nentreprises présentes sur le marché\nExemple : le marché du mobile\n•\nLe taux de pénétration des mobiles en France est passé de 40% en juin 2000 à plus de 91%\nen 2009. Le taux de pénétration est le rapport entre le nombre d’abonnements (58,9", "highlight": "pénétration"}]}, {"id": "marketing-concept-052", "chapter": "Marché", "question": "Quelles sont les quatre phases du cycle de vie d’un marché ?", "answer": "Naissance, croissance, maturité et déclin.", "sources": [{"documentId": "m2", "page": 36, "excerpt": "• Les marchés évoluent selon un cycle composé de 4 phases : naissance, croissance, maturité et déclin\n2- Le marché\n2-4) La notion de cycle de vie\nhttps://debitoor.fr/termes-comptables/cycle-de-vie-d-un-produit\nLes phases du cycle de vie d’un marché ne doivent pas être confondues avec celles du produit.\nUn marché peut avoir atteint sa phase de maturité (le marché de l’automobile par exemple) alors", "highlight": "naissance"}]}, {"id": "marketing-concept-053", "chapter": "Diagnostic et stratégie", "question": "Qu’est-ce qu’une analyse interne ?", "answer": "C’est l’analyse des ressources, compétences, fonctionnement et politique marketing de l’organisation pour identifier ses forces et ses faiblesses.", "sources": [{"documentId": "m2", "page": 37, "excerpt": "L’analyse interne\nL’analyse interne vise à créer un diagnostic interne d’une organisation analyse\nsystématique\ndes\ncaractéristiques\npropres\nà\nl’organisation\n(ressources,\nfonctionnement, compétences, politique marketing, …)\nObjectifs\n• Evaluer les atouts de l’organisation\n• Détecter les limites ou les dysfonctionnement pouvant freiner la performance\n• Préparer la matrice SWOT\n3- L’environnement interne à l’organisation", "highlight": "interne"}]}, {"id": "marketing-concept-054", "chapter": "Diagnostic et stratégie", "question": "À quoi sert la chaîne de valeur de Porter ?", "answer": "Elle identifie les activités qui créent de la valeur et permet d’en analyser les coûts.", "sources": [{"documentId": "m2", "page": 37, "excerpt": "Le modèle de la chaîne de valeur (Porter)\n3- L’environnement interne à l’organisation\nSource : https://www.e-marketing.fr/Thematique/academie-1078/fiche-\noutils-10154/chaine-valeur-306758.htm \nPermet\nd’identifier\nles\nactivités clés susceptibles\nde créer de la valeur et\nd’analyser les coûts\nLe modèle peut servir de", "highlight": "valeur"}]}, {"id": "marketing-concept-055", "chapter": "Diagnostic et stratégie", "question": "Qu’est-ce que la notoriété d’une marque ?", "answer": "C’est le degré de connaissance d’une marque et de sa catégorie de produits par le public.", "sources": [{"documentId": "m2", "page": 41, "excerpt": "La notoriété\nCapacité d’une organisation/marque à être connue\n% d’individus qui connaissent la marque et la catégorie de produits à laquelle \nelle appartient\n3- L’environnement interne à l’organisation\n3-2) La notoriété et l’image de l’organisation\nNotoriété spontanée\nNotoriété top of mind\nNotoriété assistée\n% d’individus qui citent spontanément \nla marque en question (sans aide)\n% d’individus qui citent spontanément \nla marque en 1ère réponse", "highlight": "notoriété"}]}, {"id": "marketing-concept-056", "chapter": "Diagnostic et stratégie", "question": "Quelle différence y a-t-il entre notoriété spontanée, top of mind et notoriété assistée ?", "answer": "Spontanée : la marque est citée sans aide. Top of mind : elle est citée en premier. Assistée : elle est reconnue à partir d’une liste.", "sources": [{"documentId": "m2", "page": 41, "excerpt": "Notoriété spontanée\nNotoriété top of mind\nNotoriété assistée\n% d’individus qui citent spontanément \nla marque en question (sans aide)\n% d’individus qui citent spontanément \nla marque en 1ère réponse\n% d’individus qui reconnaissent une \nmarque à partir d’une liste proposée\nPolitique produit ou politique marque (cf Marketing-mix)\nNécessité de regarder les dimensions stratégiques (objectifs, segmentation,\nciblage\net\npositionnement)\net", "highlight": "spontanée"}]}, {"id": "marketing-concept-057", "chapter": "Diagnostic et stratégie", "question": "Qu’est-ce que l’image de marque ?", "answer": "C’est l’ensemble des représentations et associations que les consommateurs attachent à une marque.", "sources": [{"documentId": "com", "page": 13, "excerpt": "Image de \nmarque\nCe que les consommateurs perçoivent \nréellement : la représentation mentale \nqu'ils s'en font\nTesla veut incarner l'innovation \ndurable, mais certains perçoivent une \nimage liée à Elon Musk\nRéputation\nL'image dans la durée, façonnée par \nl'expérience, le bouche-à-oreille, les \nmédias\nAmazon : image d'efficacité, mais \nréputation ternie par les critiques sur \nses conditions de travail", "highlight": "Image de"}]}, {"id": "marketing-concept-058", "chapter": "Diagnostic et stratégie", "question": "Quelles sont les stratégies génériques de Porter ?", "answer": "La domination par les coûts, la différenciation et la concentration ou focalisation.", "sources": [{"documentId": "m2", "page": 42, "excerpt": "Les stratégies génériques de Porter\n3- L’environnement interne à l’organisation\n3-4) L’avantage concurrentiel\nLa situation de l’organisation se caractérise par \ndes coûts faibles\nL’offre est perçue comme étant unique par \nles consommateurs\nAvantage stratégique\nLié au coût de l’offre\nLié à la différenciation de \nl’offre\nCible\nSecteur entier (cible \nlarge)\nDomination par les coûts\nDifférenciation\nSecteur particulier (cible \nrestreinte)", "highlight": "Porter"}]}, {"id": "marketing-concept-059", "chapter": "Diagnostic et stratégie", "question": "Que signifie SWOT ?", "answer": "Strengths, Weaknesses, Opportunities, Threats : forces, faiblesses, opportunités et menaces.", "sources": [{"documentId": "m3", "page": 5, "excerpt": "= diagnostic stratégique S.W.O.T. (Strengths, Weakness, Opportunities, Threats)\n•\nL’analyse SWOT pour évaluer les forces, les faiblesses, les opportunités et les \nmenaces de l’organisation en question\n•\nProvient de l’analyse de l’environnement (interne/externe) et du marché\n•\nPoint de vue interne à l’organisation \n1- Stratégie marketing : une démarche \nanalysée, planifiée, mise en œuvre et contrôlée", "highlight": "S.W.O.T"}]}, {"id": "marketing-concept-060", "chapter": "Diagnostic et stratégie", "question": "Quelle différence y a-t-il entre les éléments internes et externes du SWOT ?", "answer": "Les forces et faiblesses sont internes à l’organisation. Les opportunités et menaces viennent de l’environnement externe.", "sources": [{"documentId": "m3", "page": 6, "excerpt": "Capacités internes pouvant aider \nl’organisation à atteindre ses objectifs\ne.g. notoriété, innovation, …\nFaiblesses (Weakness)\nLimites internes qui peuvent empêcher \nl’organisation d’atteindre ses objectifs\ne.g. manque de reconnaissance de la marque\nOpportunités (Opportunities)\nFacteurs externes que l’organisation peut \nexploiter à son avantage\ne.g. émergence du numérique, nouvelles habitudes\nMenaces (Threats)", "highlight": "internes"}]}, {"id": "marketing-concept-061", "chapter": "Diagnostic et stratégie", "question": "Quelles sont les quatre fonctions du pilotage marketing ?", "answer": "Analyse, planification, implémentation et contrôle. La démarche est itérative.", "sources": [{"documentId": "m3", "page": 4, "excerpt": "contrôle et analyse…)\n1- Stratégie marketing : une démarche \nanalysée, planifiée, mise en œuvre et contrôlée\n1-1) La démarche globale\nAnalyse\nPlanification\nDéveloppement de plans \nstratégiques\nDéveloppement de plans \nmarketing \nImplémentation\nMis en œuvre des plans\nContrôle\nMesure des résultats\nEvaluation des résultats\nAction corrective\n4 fonctions pour une démarche itérative", "highlight": "analyse"}]}, {"id": "marketing-concept-062", "chapter": "Diagnostic et stratégie", "question": "Qu’est-ce que l’implémentation marketing ?", "answer": "C’est la mise en œuvre concrète de la stratégie prévue dans le plan marketing : qui agit, où, quand et comment.", "sources": [{"documentId": "m3", "page": 9, "excerpt": "Etape 3 : L’implémentation marketing\n= Mettre en œuvre la stratégie marketing décrite dans la planification\n• Se situe ici dans le marketing opérationnel (cf séquence 1)\nS’intéresse au qui, au où, au quand et au comment des activités marketing\n1- Stratégie marketing : une démarche \nanalysée, planifiée, mise en œuvre et contrôlée\n1-4) L’implémentation marketing\nPour fonctionner, l’implémentation de la stratégie doit être en", "highlight": "implémentation"}]}, {"id": "marketing-concept-063", "chapter": "Diagnostic et stratégie", "question": "Quelles sont les trois étapes du contrôle marketing ?", "answer": "Mesurer les performances, comparer les résultats aux objectifs, puis mettre en place des actions correctrices.", "sources": [{"documentId": "m3", "page": 10, "excerpt": "Etape 4 : Contrôle marketing\nNécessité d’effectuer un contrôle constant des actions mises en place\n3 étapes :\n1. Mesurer les performances des actions marketing\n2. Evaluer l’écart entre les performances réalisées et les performances espérées en objectifs\n3. Mettre en place des actions correctrices pour réduire cet écart\n1- Stratégie marketing : une démarche \nanalysée, planifiée, mise en œuvre et contrôlée\n1-5) Le contrôle marketing", "highlight": "Contrôle"}]}, {"id": "marketing-concept-064", "chapter": "Diagnostic et stratégie", "question": "Quelles sont les quatre stratégies de croissance d’Ansoff ?", "answer": "Pénétration de marché : produits et marchés existants. Développement de marché : produits existants et nouveaux marchés. Développement de produits : nouveaux produits et marchés existants. Diversification : nouveaux produits et nouveaux marchés.", "sources": [{"documentId": "m3", "page": 8, "excerpt": "Pénétration de marché développer les ventes \ndes produits existants auprès des marchés actuels \n(attirer, convaincre, accroître)\n•\nDéveloppement/extension de marché \nintroduire des produits actuels sur de nouveaux \nmarchés (e.g. sur un plan géographique)\n•\nDéveloppement de produits accroître les \nventes avec de nouveaux produits pour les cibles \nactuelles\n•\nDiversification développer des nouveaux \nproduits pour de nouveaux marchés\n1\n2\n3", "highlight": "Pénétration"}]}, {"id": "marketing-concept-065", "chapter": "Marketing mix", "question": "Qu’est-ce que le marketing mix ?", "answer": "C’est l’ensemble cohérent des outils dont dispose l’entreprise pour atteindre ses objectifs sur le marché visé.", "sources": [{"documentId": "m3", "page": 11, "excerpt": "Le marketing mix = « ensemble des outils à la disposition de l’entreprise pour\natteindre ses objectifs auprès du marché visé » (Kotler et al., 2019)\n4 outils : les « 4P » de McCarthy\nIl s’agit ici, d’analyser, d’organiser et de contrôler pour positionner une offre de bien et/ou de service\n2- Le marketing mix\n2-1) Présentation\nProduit\nPromotion\n(communication)\nPrix\nPlace\n(distribution)\nCible marketing\nPublicité, promotion des ventes,", "highlight": "mix"}]}, {"id": "marketing-concept-066", "chapter": "Marketing mix", "question": "Quels sont les 4P ?", "answer": "Product : produit. Price : prix. Place : distribution. Promotion : communication.", "sources": [{"documentId": "m3", "page": 11, "excerpt": "4 outils : les « 4P » de McCarthy\nIl s’agit ici, d’analyser, d’organiser et de contrôler pour positionner une offre de bien et/ou de service\n2- Le marketing mix\n2-1) Présentation\nProduit\nPromotion\n(communication)\nPrix\nPlace\n(distribution)\nCible marketing\nPublicité, promotion des ventes, \nparrainage, relations publiques, \nmédias sociaux, …\nCanaux de distribution, zone de \nchalandise, stocks/entrepôts, \nmoyens de transport, …", "highlight": "4P"}]}, {"id": "marketing-concept-067", "chapter": "Marketing mix", "question": "Quelles sont les trois dimensions du produit ?", "answer": "Les caractéristiques techniques, commerciales et psychologiques.", "sources": [{"documentId": "m3", "page": 11, "excerpt": "3 grandes dimensions : \n•\ncaractéristiques techniques (ce qu’il est)\n•\ncaractéristiques commerciales (ce qui permet de le vendre)\n•\nmarque, nom, slogan, design, couleurs, emballages, …\n•\ncaractéristiques psychologiques (ce que le consommateur achète au global, image du produit)\n2- Le marketing mix", "highlight": "dimensions"}]}, {"id": "marketing-concept-068", "chapter": "Marketing mix", "question": "Quelle différence y a-t-il entre produit intrinsèque, standard et global ?", "answer": "Le produit intrinsèque réunit les caractéristiques fondamentales. Le produit standard comprend sa présentation commerciale et sa marque. Le produit global ajoute les services associés, comme la garantie et le SAV.", "sources": [{"documentId": "m3", "page": 13, "excerpt": "Produit global\nNouveau bénéfice client en 2013 (cœur liquide) : changement de \npackaging pour communiquer sur le positionnement « santé » et \nles bénéfices de ce nouveau produit\n2- Le marketing mix\n2-2) Le produit\n•\nLes consommateurs sont (plus ou moins) sensibles à tous ces niveaux\n•\nPour les entreprises : réfléchir aux trois niveaux les uns après les autres pour offrir", "highlight": "global"}]}, {"id": "marketing-concept-069", "chapter": "Marketing mix", "question": "Qu’est-ce que le capital marque ?", "answer": "C’est l’effet de la connaissance de la marque sur la manière dont les consommateurs réagissent à son marketing.", "sources": [{"documentId": "m3", "page": 15, "excerpt": "Capital marque\n«Différence provoquée par la \nconnaissance de la marque dans la \nmanière dont les consommateurs \nréagissent à son marketing »\nQuel point commun", "highlight": "Capital"}]}, {"id": "marketing-concept-070", "chapter": "Marketing mix", "question": "Quelles sont les fonctions du packaging ?", "answer": "Fonctions techniques : protéger, conserver et faciliter l’utilisation, le transport et le stockage. Fonctions marketing : informer, identifier le produit, exprimer le positionnement et favoriser l’achat.", "sources": [{"documentId": "m3", "page": 16, "excerpt": "Le rôle du packaging\nDes fonctions techniques\n•\nProtection et conservation du produit\n•\nFacilité d’utilisation du produit\n•\nCommodité de transport, de stockage, de rangement et d’élimination du produit\n•\nProtection de l’environnement\n2- Le marketing mix\n2-2) Le produit\nLe rôle du packaging\nDes fonctions marketing\n•\nSource d’informations pratiques (origine, composition, date limite d’utilisation, etc.)\n•", "highlight": "packaging"}]}, {"id": "marketing-concept-071", "chapter": "Marketing mix", "question": "Quels facteurs influencent la fixation du prix ?", "answer": "Les coûts, la demande et la valeur perçue, les prix des concurrents, les objectifs de l’organisation, les contraintes légales et les tests de prix.", "sources": [{"documentId": "m3", "page": 20, "excerpt": "✔Les coûts doivent baisser à mesure que les ventes augmentent\n✔Tenir la concurrence à l’écart\nFacteurs influençant la fixation \ndes prix\n2- Le marketing mix\n2-3) Le prix\nFixer les \nprix\nLes coûts\nPrix des \nconcurrents\nDemande \nTests des prix\nContraintes \nlégales et \nréglementaires\nObjectifs de", "highlight": "coûts"}]}, {"id": "marketing-concept-072", "chapter": "Marketing mix", "question": "Qu’est-ce qu’une politique d’écrémage ?", "answer": "C’est une politique de lancement à prix élevé, destinée aux consommateurs les plus intéressés et solvables.", "sources": [{"documentId": "m3", "page": 20, "excerpt": "d’écrémage\nPolitique de\npénétration\n✔Assigner un prix initial élevé pour « écrémer » le marché\n✔S’adresse aux plus intéressés et les plus solvables\n✔Le positionnement doit être compatible avec un prix élevé\n✔S’assurer que les concurrents ne rentrent pas facilement sur le \nmarché en cassant les prix\n✔Assigner un prix bas pour pénétrer le marché rapidement\n✔Séduire un grand nombre de consommateurs et conquérir \nune grande part de marché", "highlight": "écrémage"}]}, {"id": "marketing-concept-073", "chapter": "Marketing mix", "question": "Qu’est-ce qu’une politique de pénétration tarifaire ?", "answer": "C’est une politique de lancement à prix bas pour attirer rapidement de nombreux acheteurs et gagner une part de marché importante.", "sources": [{"documentId": "m3", "page": 20, "excerpt": "pénétration\n✔Assigner un prix initial élevé pour « écrémer » le marché\n✔S’adresse aux plus intéressés et les plus solvables\n✔Le positionnement doit être compatible avec un prix élevé\n✔S’assurer que les concurrents ne rentrent pas facilement sur le \nmarché en cassant les prix\n✔Assigner un prix bas pour pénétrer le marché rapidement\n✔Séduire un grand nombre de consommateurs et conquérir \nune grande part de marché", "highlight": "pénétration"}]}, {"id": "marketing-concept-074", "chapter": "Marketing mix", "question": "Qu’est-ce que la distribution ?", "answer": "C’est l’ensemble des choix et actions qui rendent le produit ou service accessible au consommateur final.", "sources": [{"documentId": "m3", "page": 21, "excerpt": "accessible aux consommateurs finaux en\nchoisissant les canaux par lesquels il sera\nvendu\n2- Le marketing mix\n2-4) La distribution\nLa distribution\n• Distribution ne veut pas systématiquement dire Grande Distribution,\nGMS, Hypermarché…\n• La distribution est une étape obligée dans une entreprise qui fait suite à\nla production\n2- Le marketing mix", "highlight": "accessible"}]}, {"id": "marketing-concept-075", "chapter": "Marketing mix", "question": "Qu’est-ce qu’un circuit de distribution direct ?", "answer": "C’est un circuit dans lequel le producteur vend directement au consommateur, sans intermédiaire.", "sources": [{"documentId": "m3", "page": 22, "excerpt": "sans intermédiaire\nNe peut exister que si : producteur et\nconsommateur sont physiquement\nproches et que si producteur peut\nfaire la vente (ou déléguer à une\npoignée de distributeur proche)\n2- Le marketing mix\n2-4) La distribution\nLa distribution\nLorsque les producteurs sont « éloignés » des consommateurs :\n• Métiers différents, exigences différentes\n• Production et vente ne sont pas forcément compatibles d’un point de", "highlight": "intermédiaire"}]}, {"id": "marketing-concept-076", "chapter": "Marketing mix", "question": "Qu’est-ce que la distribution multicanale ?", "answer": "C’est l’utilisation de plusieurs canaux de distribution pour rendre l’offre accessible aux clients.", "sources": [{"documentId": "m3", "page": 23, "excerpt": "La distribution multicanale\n2- Le marketing mix\n2-4) La distribution\nles fonctions de la distribution\n2- Le marketing mix\n2-4) La distribution\nFonction transactionnelle \n+ \nFonction expérientielle\n1", "highlight": "multicanale"}]}, {"id": "marketing-concept-077", "chapter": "Marketing mix", "question": "Quelle différence y a-t-il entre communication interne et externe ?", "answer": "La communication interne s’adresse aux membres de l’organisation. La communication externe s’adresse aux publics extérieurs, notamment aux clients et prospects.", "sources": [{"documentId": "m3", "page": 27, "excerpt": "Communication interne\n•\nActions\nde\nl’organisation\nau\nsein\nde\nl’organisation\n•\nPublic visé : membres de l’organisation (ex:\nsalariés)\n•\nObjectif\n:\nmobiliser\nles\nmembres\nde\nl’organisation, les informer, développer le\nsentiment d’appartenance\n•\nExemples\n:\njournal\ninterne,\nintranet,\nnewsletter, compte-rendu de réunion, …\n2- Le marketing mix\n2-5) La communication\nCommunication\nCommunication interne\nCommunication externe\n•\nActions\nde\nl’organisation\nau", "highlight": "interne"}]}, {"id": "marketing-concept-078", "chapter": "Marketing mix", "question": "Quels sont les trois objectifs de communication ?", "answer": "Cognitif : faire connaître. Affectif : faire aimer. Conatif : faire agir.", "sources": [{"documentId": "m3", "page": 28, "excerpt": "Objectif cognitif\n2- Le marketing mix\n2-5) La communication\nFaire connaître\nFaire aimer\nFaire agir\nObjectif conatif\nObjectif affectif", "highlight": "cognitif"}]}, {"id": "marketing-concept-079", "chapter": "Marketing mix", "question": "Que signifie le modèle POEM ?", "answer": "Paid : médias payants. Owned : supports maîtrisés par la marque. Earned : visibilité obtenue auprès de tiers.", "sources": [{"documentId": "m3", "page": 29, "excerpt": "le modèle POEM\nAttention à l’opportunisme … !\n•\nCertaines\nentreprises\nsont\nclairement\npositionnées\ncomme\n« éthiques » dans leurs missions (Nature & Découvertes, The Body\nShop, Biocoop, Patagonia, Alter Eco…)\n(attention aux déconvenues)\n•\nTandis\nque\nd’autres\nfont\nsurtout\npreuve\nd’opportunisme\n(greenwashing)\n•\nOn observe en tous cas une multiplication des codes d’éthique à\nl’échelle des secteurs ou des entreprises.\n242\n2- Le marketing mix", "highlight": "POEM"}]}, {"id": "marketing-concept-080", "chapter": "Marketing mix", "question": "Qu’est-ce que le greenwashing ?", "answer": "C’est l’utilisation trompeuse ou opportuniste d’arguments environnementaux pour donner une image plus responsable que les pratiques réelles.", "sources": [{"documentId": "m3", "page": 29, "excerpt": "(greenwashing)\n•\nOn observe en tous cas une multiplication des codes d’éthique à\nl’échelle des secteurs ou des entreprises.\n242\n2- Le marketing mix", "highlight": "greenwashing"}]}, {"id": "marketing-concept-081", "chapter": "Segmentation", "question": "Quelle est la définition de la segmentation ?", "answer": "La segmentation consiste à découper un marché en groupes de consommateurs qui partagent des besoins, caractéristiques ou comportements communs.", "sources": [{"documentId": "m4", "page": 6, "excerpt": "2- Segmenter le marché\n2-1) Définition\nSegmenter = Découper le marché en groupes d’individus\npartageant des besoins, des caractéristiques ou des \ncomportements communs \nSur quels critères ??\n257\n2- Segmenter le marché\n2-1) Définition\nLes critères de segmentation\nLa segmentation géographique Où habite-t-il? Où achète-t-il?\nLa segmentation socio-démographique Qui est-il?\nLa segmentation psychographique Que pense-t-il?", "highlight": "Segmenter"}]}, {"id": "marketing-concept-082", "chapter": "Segmentation", "question": "Quels sont les principaux critères de segmentation ?", "answer": "Critères géographiques, sociodémographiques, psychographiques, avantages recherchés, comportements et caractéristiques physiques.", "sources": [{"documentId": "m4", "page": 7, "excerpt": "Principaux critères de segmentation\nGéographiques\nSocioéconomiques/démogra\nphiques\nPsychographiques\nConsommation et \néquipement\nRelatifs aux produits\n•\nrégion\n•\ntaille de la \ncommune, \n•\ntype d’habitat\n•\nquartier\n•\nâge, \n•\nSituation familiale\n•\ngenre\n•\nrevenu\n•\ntaille et composition du \nfoyer\n•\nniveau d’études\n•\nCSP\n•\nAncrage culturelle (langue, \nreligion, …)\nPar avantages recherchés\n•\nRecherche de produit santé \n(eg bio)\n•\nProduits pas chers \n•", "highlight": "critères"}]}, {"id": "marketing-concept-083", "chapter": "Segmentation", "question": "Qu’est-ce que la segmentation psychographique ?", "answer": "Elle regroupe les consommateurs selon leur personnalité, leur style de vie, leurs valeurs et leurs motivations.", "sources": [{"documentId": "m4", "page": 11, "excerpt": "2-4) La segmentation par critères psychographiques\nLes critères psychographiques\n=basés sur les caractéristiques psychologiques des consommateurs, se \nconcentrant sur les aspects intangibles \ne.g. \n•\nStyle de vie : activités, hobbies et opinions des individus tels que les sportifs, les \naventuriers, les écologistes, …\n•\nPersonnalité : progressiste, conservateur, ouvert d’esprit, humour, …\n•", "highlight": "psychographiques"}]}, {"id": "marketing-concept-084", "chapter": "Segmentation", "question": "Qu’est-ce que la segmentation comportementale ?", "answer": "Elle regroupe les consommateurs à partir de comportements observables : fréquence, quantité, occasion ou mode de consommation.", "sources": [{"documentId": "m4", "page": 13, "excerpt": "2-6) La segmentation par critères comportementaux\n•\nCritères\nbasés\nsur\nles\ncomportements\nréels,\nles\nconduites et les actes observables\n•\nDéveloppement\nde\nce\ntype\nde\nsegmentation\ngrâce\nau\ndéveloppement\ndu\ndata\nmining,\nanalyse des bases de données\n•\nLa quantité consommée\n•\nLa fréquence de consommation\n•\nLe rôle dans la situation d’achat\n•\nLa rentabilité des clients\n•\nLe mode de consommation : \nconsommation seul ou en groupe, à", "highlight": "comportementaux"}]}, {"id": "marketing-concept-085", "chapter": "Segmentation", "question": "Qu’est-ce que la segmentation par avantages recherchés ?", "answer": "Elle regroupe les consommateurs selon les bénéfices qu’ils attendent du produit.", "sources": [{"documentId": "m4", "page": 12, "excerpt": "2-5) La segmentation par avantages recherchés\nConsiste à regrouper les consommateurs en fonction de la\nsimilarité\nde\nleurs\nattentes,\npréférences\npar\nrapport\naux", "highlight": "avantages"}]}, {"id": "marketing-concept-086", "chapter": "Segmentation", "question": "Qu’est-ce que la segmentation multicritère ?", "answer": "Elle combine plusieurs critères pour former des segments plus précis et plus homogènes, mais généralement plus petits.", "sources": [{"documentId": "m4", "page": 15, "excerpt": "segmentation multicritères\n• Segmentation « multicritères » permet\nde segmenter plus étroitement et avoir des\nsegments mieux définis\n+ on affine la segmentation , + on\ns’assure\nde\nl’homogénéité\ndes\nsegments\n+ on affine la segmentation, + on\nréduit la taille de chaque segment\n+ on affine la segmentation, + on se\nspécialise sur un segment\n+ on affine la segmentation,+ il sera\ndifficile d’accéder au segment\n2- Segmenter le marché", "highlight": "multicritères"}]}, {"id": "marketing-concept-087", "chapter": "Segmentation", "question": "Quelles sont les qualités d’un segment utile ?", "answer": "Il doit être substantiel, homogène, différenciable et accessible.", "sources": [{"documentId": "m4", "page": 33, "excerpt": "Substantiel\nEn nombre \nd’individus pour \nespérer un chiffre \nd’affaires suffisant\nHomogène\nEn termes d’attentes, \nd’attitude, de \ncomportement / au \ntype de produit\nDifférenciable\nRéellement différent \ndes autres segments\nAccessible\nDoit pouvoir être ciblé \nde façon sélective par \nun mix marketing\nPour\nJustifier\nPermettre\nUne action marketing spécifique", "highlight": "Substantiel"}]}, {"id": "marketing-concept-088", "chapter": "Segmentation", "question": "Quelle différence y a-t-il entre segmentation de l’offre et de la demande ?", "answer": "La segmentation de l’offre regroupe les produits et services. La segmentation de la demande regroupe les consommateurs ou les entreprises clientes.", "sources": [{"documentId": "mf", "page": 6, "excerpt": "1.2 Segmentation de la demande et de l'offre\n•\nDemande : partitionner les consommateurs (B2C) ou les entreprises clientes (B2B) selon des critères\nqui forment des groupes homogènes (segments).\n•\nOffre : regrouper les produits et services selon leurs points communs. Idéalement, un segment de\nconsommateurs correspond à un segment de produits, mais ce n'est pas toujours le cas.\n•", "highlight": "demande"}]}, {"id": "marketing-concept-089", "chapter": "Segmentation", "question": "Qu’est-ce que la segmentation descendante ?", "answer": "Elle découpe successivement la population selon des critères choisis à l’avance. On l’appelle aussi segmentation a priori.", "sources": [{"documentId": "mf", "page": 7, "excerpt": "Descendante ou a\npriori\nOn part de toute la population et on fait des\npartitions successives selon des critères\ndéfinis à l'avance (on peut réaliser un arbre\nde segmentation)\nPour un nombre restreint de critères, des\nmarchés mûrs et des problématiques", "highlight": "Descendante"}]}, {"id": "marketing-concept-090", "chapter": "Segmentation", "question": "Qu’est-ce que la segmentation ascendante ?", "answer": "Elle regroupe les individus selon leurs ressemblances à partir de nombreuses données. On l’appelle aussi segmentation typologique.", "sources": [{"documentId": "mf", "page": 8, "excerpt": "Ascendante ou\ntypologique\nOn cherche les ressemblances entre\nindividus pour les agréger ; très grand\nnombre de données, sans savoir à l'avance\nlesquelles serviront\nAnalyses factorielles (composantes principales,\ncorrespondances) et typologiques (nuées\ndynamiques, centres mobiles, classification\nhiérarchique). Traitement statistique :\nindividus semblables regroupés en types,\ntypes les plus éloignés possible. Limite :", "highlight": "Ascendante"}]}, {"id": "marketing-concept-091", "chapter": "Segmentation", "question": "Quels critères permettent de segmenter un marché B2B ?", "answer": "Le secteur d’activité, la taille, les performances économiques, la localisation, le processus de décision, les critères de choix des fournisseurs et la fidélité.", "sources": [{"documentId": "mf", "page": 7, "excerpt": "1.4 Segmenter la demande en B2B\nMême logique que pour les particuliers, mais les décideurs sont rarement les destinataires et\nutilisateurs du produit acheté. Critères utiles :\n•\nSecteur d'activité : périmètre d'activité des entreprises acheteuses.\n•\nTaille de l'entreprise : impact sur le potentiel et le renouvellement des commandes (petits, moyens,\ngros clients).\n•\nPerformances économiques : distinguer entreprises saines et fragiles.\n•", "highlight": "B2B"}]}, {"id": "marketing-concept-092", "chapter": "Ciblage", "question": "Quelle est la définition du ciblage ?", "answer": "Le ciblage consiste à évaluer les segments puis à choisir celui ou ceux sur lesquels l’entreprise concentrera ses efforts.", "sources": [{"documentId": "m4", "page": 16, "excerpt": "Cibler = évaluer les différents segments de ce \nmarché et à choisir ceux sur lesquels elle fera \nporter son effort\nQu’est-ce que le ciblage?\n278\nEvaluer les différents segments à partir de :\n• La taille, la croissance, le consentement à payer sur le segment, l’intensité concurrentielle\nou tout autre facteur lui conférant un intérêt\n• Les objectifs et les ressources/compétences propres de votre entreprise.", "highlight": "Cibler"}]}, {"id": "marketing-concept-093", "chapter": "Ciblage", "question": "Sur quels critères choisit-on une cible ?", "answer": "On évalue l’attractivité du segment et sa compatibilité avec les objectifs, ressources et compétences de l’entreprise.", "sources": [{"documentId": "m4", "page": 16, "excerpt": "• Les objectifs et les ressources/compétences propres de votre entreprise.\nSélectionner les segments de marché visés\n• Marché/segment\ncible\n:\nEnsemble\nd’acheteurs\nayant\nen\ncommun\ncertaines\ncaractéristiques, ou partageant certains besoins auxquels l’entreprise se propose de\nrépondre.\n• La cible est plus ou moins large : du marketing indifférencié au marketing individualisé…\n3- Le ciblage\n3-1) Définition\n1", "highlight": "ressources"}]}, {"id": "marketing-concept-094", "chapter": "Ciblage", "question": "Qu’est-ce que le ciblage indifférencié ?", "answer": "Il consiste à proposer une offre commune à l’ensemble du marché, en privilégiant les besoins partagés.", "sources": [{"documentId": "m4", "page": 17, "excerpt": "Le marketing de masse ou stratégie indifférenciée\nIgnorer les différences entre individus, s’intéresser\naux besoins communs et cibler l’ensemble du marché\navec une offre unique.\nTrès présent dans la grande distribution alimentaire\n3- Le ciblage\n3-2) Les stratégies de ciblages\non propose le ou les\nmêmes\nproduits\nà\nl'ensemble du marché,\nsans tenir compte des\néventuelles différences", "highlight": "indifférenciée"}]}, {"id": "marketing-concept-095", "chapter": "Ciblage", "question": "Qu’est-ce que le ciblage différencié ?", "answer": "Il consiste à servir plusieurs segments avec une offre et un marketing mix adaptés à chacun.", "sources": [{"documentId": "m4", "page": 18, "excerpt": "Le marketing différencié ou multisegmenté\n•\nCibler plusieurs segments avec une offre\nspécifique pour chacun\n•\nOn s'adresse à plusieurs segments du marché\navec des produits distincts (e.g. Kellogg’s,\nRenault, Unilever).\n•\nAdapter le marketing mix aux besoins de", "highlight": "différencié"}]}, {"id": "marketing-concept-096", "chapter": "Ciblage", "question": "Qu’est-ce que le ciblage concentré ?", "answer": "Il consiste à concentrer les efforts sur un segment particulier. Une niche est un segment particulièrement étroit et spécifique.", "sources": [{"documentId": "m4", "page": 20, "excerpt": "On parle de stratégie de niche quand le segment \nvisé est particulièrement étroit (mais toutefois \nrentable !) et que l'offre est de ce fait très spécifique. \nL'entreprise se spécialise sur un produit pour un \nsegment de marché donné.\nLa stratégie de concentration\nou de niche : on décide de mobiliser\nses efforts sur un segment particulier du\nmarché\n3- Le ciblage", "highlight": "niche"}]}, {"id": "marketing-concept-097", "chapter": "Ciblage", "question": "Qu’est-ce que le marketing individualisé ?", "answer": "C’est l’adaptation de tout ou partie de l’offre à chaque individu. On l’appelle aussi marketing one to one.", "sources": [{"documentId": "m4", "page": 9, "excerpt": "le marketing personnalisé ou one to one : il consiste à\ndifférencier\npartiellement\nson\noffre\n(conditions\nd’achat,\ncommunication, produit ou service) pour chaque individu (ex. :\nhôtels\nCarlton,\nAmazon.com).\nCette\npersonnalisation\nou", "highlight": "one to one"}]}, {"id": "marketing-concept-098", "chapter": "Ciblage", "question": "Qu’est-ce qu’un persona ?", "answer": "C’est un personnage fictif représentant un groupe de clients, construit à partir de données réelles sur leurs profils, comportements et motivations.", "sources": [{"documentId": "m4", "page": 21, "excerpt": "⇒représentations fictives de vos clients idéaux basées sur des données démographiques, des\ncomportements, des motivations et des objectifs réels\n⇒permettent aux entreprises de mieux comprendre et de cibler leur audience, en adaptant les\nstratégies de communication et de marketing de manière plus précise", "highlight": "représentations"}]}, {"id": "marketing-concept-099", "chapter": "Positionnement", "question": "Quelle est la définition du positionnement ?", "answer": "Le positionnement vise à donner à l’offre une place claire et distinctive dans l’esprit des clients ciblés, par rapport aux concurrents.", "sources": [{"documentId": "m4", "page": 23, "excerpt": "4- Le positionnement\n4-1) Définition \nLe positionnement = conception d’un produit et de son image dans le but de lui\ndonner une place déterminée dans l’esprit des clients ciblés ; le produit/service doit\nêtre perçu par eux comme répondant avantageusement (par rapport à la concurrence)\nà l'une au moins de leurs attentes.\n292\n4- Le positionnement\n4-1) Définition \nLe positionnement", "highlight": "positionnement"}]}, {"id": "marketing-concept-100", "chapter": "Positionnement", "question": "Quelles sont les deux composantes du positionnement ?", "answer": "L’identification, qui rattache l’offre à une catégorie, et la différenciation, qui la distingue des offres concurrentes.", "sources": [{"documentId": "m4", "page": 26, "excerpt": "L’identification : rattacher le produit à une catégorie, à un \nunivers de consommation\nLa différenciation : distinguer le produit dans sa catégorie > le \npoint de différence\n4- Le positionnement", "highlight": "identification"}]}, {"id": "marketing-concept-101", "chapter": "Positionnement", "question": "Qu’est-ce que la différenciation ?", "answer": "C’est le choix d’attributs ou de bénéfices valorisés par la cible qui distinguent l’offre de celle des concurrents.", "sources": [{"documentId": "m4", "page": 27, "excerpt": "La différenciation :\nqu’est-ce qui peut distinguer mon produit/service des autres du même genre ? (NB :\nLa différence perçue est très faible dans certains secteurs (banques, sucre…))\n•\nDéterminer les attributs de valeurs susceptibles d’être pris en compte par les\nacheteurs pour ce genre de produits/services : goût, couleur, odeur, texture,\nfiabilité, prestige, naturalité, caractère équitable, circuit de distribution,", "highlight": "différenciation"}]}, {"id": "marketing-concept-102", "chapter": "Positionnement", "question": "Comment formule-t-on un énoncé de positionnement ?", "answer": "« Pour [cible], la marque X est [catégorie] qui apporte [bénéfice distinctif]. »", "sources": [{"documentId": "m4", "page": 29, "excerpt": "Enoncé de positionnement\nPour les gens qui… > cible\nLa marque X est… > identification\nQui apporte … > différenciation\n4- Le positionnement\n4-2) La démarche\nles machines Nespresso sont conçues pour révéler les saveurs\net les arômes subtils de nos cafés, pour des consommateurs\nexigeants et esthètes, afin de leur offrir une expérience\ncomplète de consommation de café d’exception.\n4- Le positionnement", "highlight": "Enoncé"}]}, {"id": "marketing-concept-103", "chapter": "Positionnement", "question": "Quels sont les critères d’un bon positionnement ?", "answer": "Il doit être attractif, différenciant, crédible, simple, profitable et pérenne.", "sources": [{"documentId": "mf", "page": 9, "excerpt": "Attractivité\nAttirant pour la cible, en phase avec ses attentes (exprimées ou latentes)\nDifférenciation\nDifférent de l'offre existante, ce qui justifie le produit\nCrédibilité\nLes consommateurs croient que le produit tiendra ses promesses\nSimple\nPeu de caractéristiques ; doit tenir en une phrase\nProfitable\nCible au potentiel économique suffisant (un segment peut être rentable pour une PME et\npas pour une multinationale)\nPérenne", "highlight": "Attractivité"}]}, {"id": "marketing-concept-104", "chapter": "Positionnement", "question": "Que signifie USP ?", "answer": "Unique Selling Proposition : une proposition de vente unique qui met en avant un bénéfice principal et distinctif.", "sources": [{"documentId": "mf", "page": 9, "excerpt": "Mettre en avant un seul bénéfice = USP (Unique Selling Proposition) : positionnement plus clair dans\nl'esprit des consommateurs. Ou plusieurs bénéfices, choisis avec des critères : importance pour la\ncible, caractère distinctif, supériorité sur la concurrence, facilité à communiquer, caractère défendable\net justifiable, rentabilité.\n•\nLe positionnement est intégré aux briefs de chaque action marketing, et sa perception par les", "highlight": "USP"}]}], "documents": ["m1", "m2", "m3", "m4", "mf"]}, {"id": "communication", "title": "Communication commerciale", "description": "Définitions et notions essentielles de communication.", "symbol": "C", "storageKey": "declic-communication-concepts-v3", "cards": [{"id": "communication-concept-001", "chapter": "1 · Les fondamentaux", "question": "Quelle est la définition de la communication d’une entreprise ?", "answer": "C’est l’ensemble des informations, messages et signaux qu’une entreprise émet, volontairement ou non, vers tous ses publics.", "sources": [{"documentId": "com", "page": 1, "excerpt": "Communication : ensemble des informations, messages et signaux de toute nature \nqu'une entreprise émet, volontairement ou non, vers tous ses publics.\n\nCommunication commerciale : ensemble des actions mises en œuvre par une \nentreprise pour influencer positivement les attitudes et comportements de ses \npublics, dans une perspective de performance économique.\n4 fonctions : INFORMER · SÉDUIRE · CONVAINCRE · FIDÉLISER\nFonction\nObjectif\nInformer", "highlight": "ensemble des informations"}]}, {"id": "communication-concept-002", "chapter": "1 · Les fondamentaux", "question": "Quelle est la définition de la communication commerciale ?", "answer": "C’est l’ensemble des actions visant à influencer positivement les attitudes et comportements des publics dans une perspective de performance économique.", "sources": [{"documentId": "com", "page": 1, "excerpt": "entreprise pour influencer positivement les attitudes et comportements de ses \npublics, dans une perspective de performance économique.\n4 fonctions : INFORMER · SÉDUIRE · CONVAINCRE · FIDÉLISER\nFonction\nObjectif\nInformer\nFaire connaître un produit ou une marque\nSéduire\nAttirer l'attention, provoquer une émotion\nConvaincre Déclencher l'achat\nFidéliser\nRenforcer la relation à long terme\n2 objectifs majeurs\n", "highlight": "influencer positivement"}]}, {"id": "communication-concept-003", "chapter": "1 · Les fondamentaux", "question": "Quelles sont les quatre fonctions de la communication commerciale ?", "answer": "Informer, séduire, convaincre et fidéliser.", "sources": [{"documentId": "com", "page": 1, "excerpt": "4 fonctions : INFORMER · SÉDUIRE · CONVAINCRE · FIDÉLISER\nFonction\nObjectif\nInformer\nFaire connaître un produit ou une marque\nSéduire\nAttirer l'attention, provoquer une émotion\nConvaincre Déclencher l'achat\nFidéliser\nRenforcer la relation à long terme\n2 objectifs majeurs\n\nÉconomiques : augmenter les ventes, conquérir des parts de marché, fidéliser la \nclientèle.\n\nSymboliques : créer de la valeur immatérielle (image, notoriété, crédibilité).", "highlight": "INFORMER"}]}, {"id": "communication-concept-004", "chapter": "1 · Les fondamentaux", "question": "Quelle différence y a-t-il entre objectifs économiques et symboliques de communication ?", "answer": "Les objectifs économiques concernent notamment les ventes, les parts de marché et la fidélisation. Les objectifs symboliques concernent l’image, la notoriété et la crédibilité.", "sources": [{"documentId": "com", "page": 1, "excerpt": "Symboliques : créer de la valeur immatérielle (image, notoriété, crédibilité).\nÉvolution\n\nAux acteurs classiques s'ajoutent les influenceurs et créateurs de contenu.\n\nEnjeux : relation durable, montrer ses valeurs, gérer sa réputation.\nTypes de communication\nObjet de la communication\nType\nProduits / services\nCommunication de produit\nLa marque\nCommunication de marque\nL'entreprise\nCommunication institutionnelle", "highlight": "Symboliques"}]}, {"id": "communication-concept-005", "chapter": "1 · Les fondamentaux", "question": "Qu’est-ce que la communication institutionnelle ?", "answer": "C’est la communication qui porte sur l’entreprise dans son ensemble.", "sources": [{"documentId": "com", "page": 1, "excerpt": "Communication institutionnelle\nSecteur ou entreprise en crise Communication de crise\nLe personnel\nCommunication interne\nActionnaires / investisseurs\nCommunication externe (financière)\nLes candidats", "highlight": "institutionnelle"}]}, {"id": "communication-concept-006", "chapter": "1 · Les fondamentaux", "question": "Qu’est-ce que la communication de produit ?", "answer": "Elle fait connaître le produit et ses caractéristiques, en restant cohérente avec l’image de marque.", "sources": [{"documentId": "com", "page": 2, "excerpt": "Com. de produit : faire connaître le produit et ses caractéristiques, en restant \ncohérente avec l'image de marque.\n\nCom. de marque : utile sur les marchés très concurrentiels ou les produits à forte \nvaleur imaginaire ; crée un territoire de marque distinctif qui fidélise.\nPlace dans le mix marketing\n4P = Produit · Prix · Place · Promotion (= communication).\n\nLa communication est la partie visible du marketing et assure la cohérence du mix.\n", "highlight": "Com. de produit"}]}, {"id": "communication-concept-007", "chapter": "1 · Les fondamentaux", "question": "Qu’est-ce que la communication de marque ?", "answer": "Elle construit un territoire de marque distinctif et favorise la différenciation et la fidélisation.", "sources": [{"documentId": "com", "page": 2, "excerpt": "Com. de marque : utile sur les marchés très concurrentiels ou les produits à forte \nvaleur imaginaire ; crée un territoire de marque distinctif qui fidélise.\nPlace dans le mix marketing\n4P = Produit · Prix · Place · Promotion (= communication).\n\nLa communication est la partie visible du marketing et assure la cohérence du mix.\n\nUne stratégie = organiser des choix cohérents.\n", "highlight": "Com. de marque"}]}, {"id": "communication-concept-008", "chapter": "1 · Les fondamentaux", "question": "Qu’est-ce qu’un annonceur ?", "answer": "C’est l’entreprise qui commande une campagne de communication.", "sources": [{"documentId": "com", "page": 2, "excerpt": "Annonceurs\nEntreprises qui commandent la campagne (Nike, Decathlon, Orange)\nAgences\nConçoivent les campagnes (Publicis, BETC)\nMédias et supports Diffusent le message (presse, télé, affichage, réseaux sociaux, \ninfluenceurs)\nRégies publicitaires Vendent et achètent des espaces pub selon prix, horaire, emplacement, \njour\nPublics\nConsommateurs, prescripteurs, leaders d'opinion, associations, \ninstitutions", "highlight": "Annonceurs"}]}, {"id": "communication-concept-009", "chapter": "1 · Les fondamentaux", "question": "Quel est le rôle d’une agence de communication ?", "answer": "Elle conçoit les campagnes de communication.", "sources": [{"documentId": "com", "page": 2, "excerpt": "Agences\nConçoivent les campagnes (Publicis, BETC)\nMédias et supports Diffusent le message (presse, télé, affichage, réseaux sociaux, \ninfluenceurs)\nRégies publicitaires Vendent et achètent des espaces pub selon prix, horaire, emplacement, \njour\nPublics\nConsommateurs, prescripteurs, leaders d'opinion, associations, \ninstitutions\nMétiers d'une agence : département stratégie (planneur stratégique) · service médias ·", "highlight": "Agences"}]}, {"id": "communication-concept-010", "chapter": "1 · Les fondamentaux", "question": "Qu’est-ce qu’une régie publicitaire ?", "answer": "C’est un intermédiaire qui commercialise les espaces publicitaires des médias auprès des annonceurs et des agences.", "sources": [{"documentId": "com", "page": 5, "excerpt": "Régies publicitaires : elles commercialisent, auprès des annonceurs et des agences, \nles espaces publicitaires des médias dont elles ont la charge. Elles sont intermédiaires \nentre l'annonceur et le diffuseur.\n\nAgences, détail des métiers : les créatifs incluent le directeur de la création, les \ndirecteurs artistiques, les concepteurs-rédacteurs, graphistes, motion designers,", "highlight": "Régie"}]}, {"id": "communication-concept-011", "chapter": "1 · Les fondamentaux", "question": "Qu’est-ce que la saturation publicitaire ?", "answer": "C’est la surabondance de messages publicitaires reçus par le public. Elle peut entraîner une fatigue et une moindre attention aux publicités.", "sources": [{"documentId": "com", "page": 2, "excerpt": "Saturation publicitaire : trop de messages.\n\nFragmentation des audiences : chacun consomme des médias différents.\n\nDigital : réseaux sociaux, data, ciblage personnalisé.\n\nAttentes sociétales : transparence, durabilité, inclusion.\n\nInstantanéité : la marque doit être active ; un bad buzz est un danger.", "highlight": "Saturation"}]}, {"id": "communication-concept-012", "chapter": "1 · Les fondamentaux", "question": "Qu’est-ce que la fragmentation des audiences ?", "answer": "C’est la dispersion des publics entre de nombreux médias et supports.", "sources": [{"documentId": "com", "page": 2, "excerpt": "Fragmentation des audiences : chacun consomme des médias différents.\n\nDigital : réseaux sociaux, data, ciblage personnalisé.\n\nAttentes sociétales : transparence, durabilité, inclusion.\n\nInstantanéité : la marque doit être active ; un bad buzz est un danger.", "highlight": "Fragmentation"}]}, {"id": "communication-concept-013", "chapter": "2 · La stratégie", "question": "Quelle est la définition d’une stratégie de communication ?", "answer": "C’est l’ensemble des choix et orientations qui guident les actions de communication pour atteindre des objectifs précis auprès de cibles identifiées.", "sources": [{"documentId": "com", "page": 3, "excerpt": "Ensemble des choix et orientations qui guident les actions de communication d'une \norganisation pour atteindre des objectifs précis auprès de cibles identifiées.\nElle répond à : quoi dire, comment, à qui, quand, pourquoi ? (le bon message, à la bonne \ncible, par le bon canal).\nElle doit être : alignée avec la stratégie globale · cohérente avec l'image de marque · \nmesurable (indicateurs de performance).\nLes 3 étapes\nÉtape 1 – Diagnostic\n", "highlight": "choix et orientations"}]}, {"id": "communication-concept-014", "chapter": "2 · La stratégie", "question": "Quelles sont les quatre étapes d’une stratégie de communication ?", "answer": "Diagnostic, objectifs de communication, cibles, puis positionnement et message ou stratégie créative.", "sources": [{"documentId": "com", "page": 6, "excerpt": "Les 4 étapes\n1. Diagnostic · 2. Objectif de communication · 3. Cibles · 4. Positionnement et message \n(stratégie créative)\nDiagnostic, compléments : outil = matrice SWOT (forces, faiblesses, opportunités, \nmenaces). L'ensemble de ces données approfondies = audit de la communication.\nHiérarchie des effets appliquée aux objectifs :\nStade\nIdée\nContenu\nCognitif Faire savoir Notoriété, info produit, stimuler l'attention", "highlight": "Les 4 étapes"}]}, {"id": "communication-concept-015", "chapter": "2 · La stratégie", "question": "Qu’est-ce qu’un audit de communication ?", "answer": "C’est l’analyse approfondie de la situation de communication de l’organisation. Le diagnostic est notamment synthétisé dans une matrice SWOT.", "sources": [{"documentId": "com", "page": 6, "excerpt": "menaces). L'ensemble de ces données approfondies = audit de la communication.\nHiérarchie des effets appliquée aux objectifs :\nStade\nIdée\nContenu\nCognitif Faire savoir Notoriété, info produit, stimuler l'attention\nAffectif Faire aimer Attrait, effet sur l'image, préférence, éveiller l'intérêt\nConatif Faire agir\nAchat, conviction, créer du trafic, inciter à l'essai\nCibles, compléments\n", "highlight": "audit"}]}, {"id": "communication-concept-016", "chapter": "2 · La stratégie", "question": "Quels sont les trois objectifs de communication ?", "answer": "Cognitif : faire savoir ou connaître. Affectif : faire aimer. Conatif : faire agir.", "sources": [{"documentId": "com", "page": 6, "excerpt": "Cognitif Faire savoir Notoriété, info produit, stimuler l'attention\nAffectif Faire aimer Attrait, effet sur l'image, préférence, éveiller l'intérêt\nConatif Faire agir\nAchat, conviction, créer du trafic, inciter à l'essai\nCibles, compléments\n\nCible marketing : clients actuels et prospects que l'on peut toucher. Elle prend en \ncompte un marché identifié, la concurrence et les clients potentiels, pour répondre aux", "highlight": "Faire savoir"}]}, {"id": "communication-concept-017", "chapter": "2 · La stratégie", "question": "Que signifie SMART pour un objectif ?", "answer": "Spécifique, mesurable, atteignable, réaliste et temporel.", "sources": [{"documentId": "com", "page": 3, "excerpt": "Méthode SMART\nLettre\nCritère\nSens\nS\nSpécifique Précis et clair\nM\nMesurable Peut être mesuré\nA\nAtteignable Réalisable avec les compétences et ressources disponibles\nR\nRéaliste\nEn adéquation avec les contraintes et capacités actuelles\nT\nTemporel\nDate d'échéance définie\nÉtape 3 – Cibles\n\nStratégie marketing : segmentation → ciblage → positionnement.\n\nCible marketing = à qui l'entreprise vend. Cible de communication = à qui \nelle parle.\n", "highlight": "SMART"}]}, {"id": "communication-concept-018", "chapter": "2 · La stratégie", "question": "Quelle différence y a-t-il entre cible marketing et cible de communication ?", "answer": "La cible marketing désigne les personnes à qui l’entreprise vend. La cible de communication désigne les personnes à qui elle s’adresse.", "sources": [{"documentId": "com", "page": 6, "excerpt": "Cible marketing : clients actuels et prospects que l'on peut toucher. Elle prend en \ncompte un marché identifié, la concurrence et les clients potentiels, pour répondre aux \nbesoins du mix marketing (prix, distribution…).\n\nCible principale : personnes directement concernées par le produit ou service ; \ncaractérisée par âge, sexe, lieu géographique, centres d'intérêt, CSP.\n", "highlight": "Cible marketing"}]}, {"id": "communication-concept-019", "chapter": "2 · La stratégie", "question": "Qu’est-ce que la cible principale ?", "answer": "Ce sont les personnes directement concernées par le produit ou le service.", "sources": [{"documentId": "com", "page": 6, "excerpt": "Cible principale : personnes directement concernées par le produit ou service ; \ncaractérisée par âge, sexe, lieu géographique, centres d'intérêt, CSP.\n\nHiérarchisation des cibles : prise en compte du circuit de distribution et \ndu processus de décision d'achat(consommateur, acheteur, prescripteurs).\nConnaître et comprendre ses cibles : l'insight\n\nÀ comprendre : motivations profondes (hédonistes, oblatives, auto-", "highlight": "Cible principale"}]}, {"id": "communication-concept-020", "chapter": "2 · La stratégie", "question": "Qu’est-ce que le cœur de cible ?", "answer": "C’est le sous-ensemble prioritaire de la cible principale.", "sources": [{"documentId": "com", "page": 4, "excerpt": "Cœur de cible : sous-ensemble de la cible principale, touché en premier, avec des \ncritères supplémentaires pour resserrer.\n\nCibles secondaires : ne concernent pas directement la marque mais la \nrecommandent : prescripteurs, distributeurs (force de vente), journalistes.\nMémo express\n\n4 fonctions : informer, séduire, convaincre, fidéliser.\n\n4P : produit, prix, place, promotion.\n\n3 objectifs : notoriété, image, action.\n", "highlight": "Cœur de cible"}]}, {"id": "communication-concept-021", "chapter": "2 · La stratégie", "question": "Qu’est-ce qu’une cible secondaire ?", "answer": "C’est un public qui peut recommander, relayer ou influencer l’achat sans être la cible principale.", "sources": [{"documentId": "com", "page": 4, "excerpt": "Cibles secondaires : ne concernent pas directement la marque mais la \nrecommandent : prescripteurs, distributeurs (force de vente), journalistes.\nMémo express\n\n4 fonctions : informer, séduire, convaincre, fidéliser.\n\n4P : produit, prix, place, promotion.\n\n3 objectifs : notoriété, image, action.\n\nSMART : spécifique, mesurable, atteignable, réaliste, temporel.\n\nCiblage : principale → cœur de cible → secondaires.", "highlight": "Cibles secondaires"}]}, {"id": "communication-concept-022", "chapter": "2 · La stratégie", "question": "Qu’est-ce qu’un insight consommateur ?", "answer": "C’est la perception d’un problème ou d’un dilemme non résolu dans une catégorie de produits. Il révèle une motivation, un besoin ou un manque.", "sources": [{"documentId": "com", "page": 6, "excerpt": "Connaître et comprendre ses cibles : l'insight\n\nÀ comprendre : motivations profondes (hédonistes, oblatives, auto-\nexpression), freins (peurs, inhibitions, risques), besoins, attentes, perception.\n\nInsight : perception par le consommateur d'un problème ou dilemme irrésolu sur la \ncatégorie de produits où la marque opère. Notion clé : motivation ou besoin sous-\njacent, signe avant-coureur, constat d'un manque.\n", "highlight": "insight"}]}, {"id": "communication-concept-023", "chapter": "2 · La stratégie", "question": "Quelles sont les trois grandes motivations du consommateur ?", "answer": "Hédonistes : se faire plaisir. Oblatives : faire plaisir aux autres. Auto-expression : exprimer sa personnalité ou l’image de soi.", "sources": [{"documentId": "com", "page": 6, "excerpt": "À comprendre : motivations profondes (hédonistes, oblatives, auto-\nexpression), freins (peurs, inhibitions, risques), besoins, attentes, perception.\n\nInsight : perception par le consommateur d'un problème ou dilemme irrésolu sur la \ncatégorie de produits où la marque opère. Notion clé : motivation ou besoin sous-\njacent, signe avant-coureur, constat d'un manque.\n\nComment l'analyser : observation → motivation → frein → réponse de la marque.\n", "highlight": "hédonistes"}]}, {"id": "communication-concept-024", "chapter": "2 · La stratégie", "question": "Quels sont les principaux freins à l’achat ?", "answer": "Les peurs, les inhibitions et les risques perçus.", "sources": [{"documentId": "com", "page": 6, "excerpt": "expression), freins (peurs, inhibitions, risques), besoins, attentes, perception.\n\nInsight : perception par le consommateur d'un problème ou dilemme irrésolu sur la \ncatégorie de produits où la marque opère. Notion clé : motivation ou besoin sous-\njacent, signe avant-coureur, constat d'un manque.\n\nComment l'analyser : observation → motivation → frein → réponse de la marque.\n", "highlight": "freins"}]}, {"id": "communication-concept-025", "chapter": "2 · La stratégie", "question": "Quelle est la définition du positionnement ?", "answer": "C’est l’ensemble des traits saillants qui permettent au consommateur d’identifier l’offre et de la différencier de ses concurrents.", "sources": [{"documentId": "com", "page": 6, "excerpt": "Positionnement (Ries et Trout) : ensemble des traits saillants qui permettent aux \nconsommateurs d'identifier le produit et de le différencier de l'univers des produits \nconcurrents.\nPourquoi positionner ? Se différencier des concurrents · répondre aux attentes clients · être", "highlight": "Positionnement (Ries"}]}, {"id": "communication-concept-026", "chapter": "2 · La stratégie", "question": "Qu’est-ce qu’une copy stratégie ?", "answer": "C’est un brief créatif qui synthétise la réflexion stratégique et fixe ce que le message doit communiquer.", "sources": [{"documentId": "com", "page": 7, "excerpt": "La stratégie créative = copy stratégie (brief créatif)\nElle expose les points clés de la réflexion stratégique et pose les axes de création. C'est le plan \nqui permet à l'annonceur de comprendre le travail de l'agence, une méthode synthétique pour \nexprimer ce que le message doit communiquer.\nÉlément\nDéfinition\nPromesse\nCe que la marque promet d'apporter au consommateur. Elle doit \nêtre unique (USP), simple (adaptée aux connaissances de la", "highlight": "copy stratégie"}]}, {"id": "communication-concept-027", "chapter": "2 · La stratégie", "question": "Quels sont les éléments d’une copy stratégie ?", "answer": "Promesse, bénéfice consommateur, avantage produit, ton, preuves et contraintes.", "sources": [{"documentId": "com", "page": 7, "excerpt": "Bénéfice \nconsommateur\nCe que le consommateur retire de l'utilisation de la marque\nAvantage produit Performance du produit\nTon\nClimat / atmosphère du message : explicatif, démonstratif, informatif, \nhumoristique, imaginaire, symbolique\nPreuves\nJustifier la promesse par des éléments concrets\nContraintes\nLégales, de temps, de budget, respect de la charte graphique", "highlight": "Bénéfice \nconsommateur"}]}, {"id": "communication-concept-028", "chapter": "2 · La stratégie", "question": "Qu’est-ce que la promesse publicitaire ?", "answer": "C’est ce que la marque promet d’apporter au consommateur. Elle doit être unique, simple et ne pas enfermer la création.", "sources": [{"documentId": "com", "page": 7, "excerpt": "Promesse\nCe que la marque promet d'apporter au consommateur. Elle doit \nêtre unique (USP), simple (adaptée aux connaissances de la \ncible), abstraite (pour ne pas contraindre la création)\nBénéfice \nconsommateur\nCe que le consommateur retire de l'utilisation de la marque\nAvantage produit Performance du produit\nTon\nClimat / atmosphère du message : explicatif, démonstratif, informatif, \nhumoristique, imaginaire, symbolique\nPreuves", "highlight": "Promesse"}]}, {"id": "communication-concept-029", "chapter": "2 · La stratégie", "question": "Quelle différence y a-t-il entre bénéfice consommateur et avantage produit ?", "answer": "Le bénéfice est ce que le consommateur retire de l’usage. L’avantage produit est une performance ou caractéristique du produit.", "sources": [{"documentId": "com", "page": 7, "excerpt": "Avantage produit Performance du produit\nTon\nClimat / atmosphère du message : explicatif, démonstratif, informatif, \nhumoristique, imaginaire, symbolique\nPreuves\nJustifier la promesse par des éléments concrets\nContraintes\nLégales, de temps, de budget, respect de la charte graphique\nElle fixe un cadre à partir duquel la création se développe, et doit reposer sur un bénéfice \ntangible, simple, clair et cohérent.", "highlight": "Avantage produit"}]}, {"id": "communication-concept-030", "chapter": "2 · La stratégie", "question": "Qu’est-ce que le ton d’un message publicitaire ?", "answer": "C’est le climat ou l’atmosphère du message : informatif, démonstratif, humoristique, imaginaire ou symbolique, notamment.", "sources": [{"documentId": "com", "page": 7, "excerpt": "Climat / atmosphère du message : explicatif, démonstratif, informatif, \nhumoristique, imaginaire, symbolique\nPreuves\nJustifier la promesse par des éléments concrets\nContraintes\nLégales, de temps, de budget, respect de la charte graphique\nElle fixe un cadre à partir duquel la création se développe, et doit reposer sur un bénéfice \ntangible, simple, clair et cohérent.", "highlight": "Climat"}]}, {"id": "communication-concept-031", "chapter": "2 · La stratégie", "question": "À quoi servent les preuves dans une copy stratégie ?", "answer": "Elles justifient la promesse par des éléments concrets.", "sources": [{"documentId": "com", "page": 7, "excerpt": "Justifier la promesse par des éléments concrets\nContraintes\nLégales, de temps, de budget, respect de la charte graphique\nElle fixe un cadre à partir duquel la création se développe, et doit reposer sur un bénéfice \ntangible, simple, clair et cohérent.\nExemple : agence de voyage low cost. Promesse : les prix les plus bas · Bénéfice : voyager \nplus · Ton : détendu, exotique · Preuve : les prix de l'agence · Contraintes : charte graphique,", "highlight": "Justifier la promesse"}]}, {"id": "communication-concept-032", "chapter": "2 · La stratégie", "question": "Quelles contraintes encadrent une copy stratégie ?", "answer": "Les contraintes peuvent être légales, temporelles, budgétaires ou liées à la charte graphique.", "sources": [{"documentId": "com", "page": 7, "excerpt": "Contraintes\nLégales, de temps, de budget, respect de la charte graphique\nElle fixe un cadre à partir duquel la création se développe, et doit reposer sur un bénéfice \ntangible, simple, clair et cohérent.\nExemple : agence de voyage low cost. Promesse : les prix les plus bas · Bénéfice : voyager \nplus · Ton : détendu, exotique · Preuve : les prix de l'agence · Contraintes : charte graphique, \nlogo du partenaire.", "highlight": "Contraintes"}]}, {"id": "communication-concept-033", "chapter": "3 · Les théories", "question": "Quels sont les éléments du modèle de Lasswell ?", "answer": "L’émetteur, le message, la cible, le canal et l’effet. Le modèle se résume par « Qui dit quoi, à qui, par quel canal, avec quel effet ? ».", "sources": [{"documentId": "com", "page": 7, "excerpt": "« Qui dit quoi, à qui, par quel canal, avec quel effet ? »\nQuestion\nÉlément", "highlight": "Qui dit quoi"}]}, {"id": "communication-concept-034", "chapter": "3 · Les théories", "question": "Quelle est la principale limite du modèle de Shannon et Weaver présenté dans le cours ?", "answer": "C’est un modèle linéaire ou télégraphique qui ne prend pas en compte la rétroaction.", "sources": [{"documentId": "com", "page": 8, "excerpt": "B. Modèle de Shannon et Weaver (1949) : modèle télégraphique\nAbsence de rétroaction, modèle simpliste.\nC. Modèle de Jakobson (1960) : les fonctions du langage\nFonction\nRôle\nRéférentielle\nInformer\nExpressive\nÉmouvoir\nConative\nInfluencer\nPhatique\nCréer du contact\nPoétique\nJeu sur la forme\nMétalinguistique Expliquer un code\n2. Wiener et la cybernétique (1948)\n\nSystème : ensemble d'éléments interdépendants tels que la modification de l'un", "highlight": "Shannon"}]}, {"id": "communication-concept-035", "chapter": "3 · Les théories", "question": "Quelles sont les six fonctions du langage de Jakobson ?", "answer": "Référentielle, expressive, conative, phatique, poétique et métalinguistique.", "sources": [{"documentId": "com", "page": 8, "excerpt": "C. Modèle de Jakobson (1960) : les fonctions du langage\nFonction\nRôle\nRéférentielle\nInformer\nExpressive\nÉmouvoir\nConative\nInfluencer\nPhatique\nCréer du contact\nPoétique\nJeu sur la forme\nMétalinguistique Expliquer un code\n2. Wiener et la cybernétique (1948)\n\nSystème : ensemble d'éléments interdépendants tels que la modification de l'un \nentraîne celle de tous les autres.\n", "highlight": "Jakobson"}]}, {"id": "communication-concept-036", "chapter": "3 · Les théories", "question": "Qu’est-ce que la rétroaction ?", "answer": "C’est le retour d’information qui permet à un système de connaître son état et de se réguler.", "sources": [{"documentId": "com", "page": 8, "excerpt": "Absence de rétroaction, modèle simpliste.\nC. Modèle de Jakobson (1960) : les fonctions du langage\nFonction\nRôle\nRéférentielle\nInformer\nExpressive\nÉmouvoir\nConative\nInfluencer\nPhatique\nCréer du contact\nPoétique\nJeu sur la forme\nMétalinguistique Expliquer un code\n2. Wiener et la cybernétique (1948)\n\nSystème : ensemble d'éléments interdépendants tels que la modification de l'un \nentraîne celle de tous les autres.\n", "highlight": "rétroaction"}]}, {"id": "communication-concept-037", "chapter": "3 · Les théories", "question": "Qu’est-ce que la cybernétique ?", "answer": "C’est la science des communications et de la régulation dans l’être vivant et la machine.", "sources": [{"documentId": "com", "page": 8, "excerpt": "2. Wiener et la cybernétique (1948)\n\nSystème : ensemble d'éléments interdépendants tels que la modification de l'un \nentraîne celle de tous les autres.\n\nIl se régule grâce aux boucles de rétroaction (informations sur son état et celui de son \nenvironnement).\n\nUn système est ouvert car il communique sans interruption avec son \nenvironnement. Un système stable n'est pas nécessairement statique.\n", "highlight": "cybernétique"}]}, {"id": "communication-concept-038", "chapter": "3 · Les théories", "question": "Quel principe fondamental retient-on de l’école de Palo Alto ?", "answer": "On ne peut pas ne pas communiquer : les comportements et le non-verbal transmettent aussi des messages.", "sources": [{"documentId": "com", "page": 8, "excerpt": "1. On ne peut pas ne pas communiquer : même le silence, la posture ou le design \nminimaliste d'un produit envoient un message.\n2. Tout message a deux niveaux : contenu (ce qui est dit) + relation (la manière dont \nc'est dit).\n3. La communication est circulaire : système d'interactions, pas une ligne droite (ex. \npost TikTok d'une marque → commentaires → réponse → co-construction du \nmessage).", "highlight": "On ne peut pas"}]}, {"id": "communication-concept-039", "chapter": "3 · Les théories", "question": "Quels sont les deux niveaux d’un message selon Palo Alto ?", "answer": "Le contenu, c’est-à-dire ce qui est dit, et la relation, c’est-à-dire la manière dont c’est dit.", "sources": [{"documentId": "com", "page": 8, "excerpt": "2. Tout message a deux niveaux : contenu (ce qui est dit) + relation (la manière dont \nc'est dit).\n3. La communication est circulaire : système d'interactions, pas une ligne droite (ex. \npost TikTok d'une marque → commentaires → réponse → co-construction du \nmessage).\n4. Verbal et non verbal : gestes, images, couleurs véhiculent un sens aussi fort que les \nmots.", "highlight": "deux niveaux"}]}, {"id": "communication-concept-040", "chapter": "3 · Les théories", "question": "Que signifient logos, pathos et ethos ?", "answer": "Logos : persuasion par la raison et la démonstration. Pathos : persuasion par l’émotion. Ethos : persuasion par le statut et la crédibilité de l’émetteur.", "sources": [{"documentId": "com", "page": 9, "excerpt": "LOGOS\nFonctionnelle ou démonstrative : met en avant les performances du produit \nface aux problèmes du consommateur\nPATHOS\nÉmotionnelle : pulsions, motivations hédonistes, d'auto-expression, oblatives\nETHOS\nMet en avant le statut de la marque ou de l'entreprise\nb) Création d'automatismes : modèle behavioriste\n\nLes comportements sont des réponses à des stimuli du monde extérieur.\n", "highlight": "LOGOS"}]}, {"id": "communication-concept-041", "chapter": "3 · Les théories", "question": "Qu’est-ce que le modèle behavioriste ?", "answer": "Il explique les comportements comme des réponses à des stimuli extérieurs. La répétition et la nature des stimuli favorisent le conditionnement.", "sources": [{"documentId": "com", "page": 9, "excerpt": "b) Création d'automatismes : modèle behavioriste\n\nLes comportements sont des réponses à des stimuli du monde extérieur.\n\nDéveloppé par Watson, Pavlov, Bekhterev. Réponses conditionnées par la fréquence \net la nature des stimuli.\n\nInspiré des théoriciens de la propagande politique (Tchakhotine).\nc) Persuasion logique : modèle de la hiérarchie des effets\nLe comportement est le résultat d'un processus mental d'acquisition et de traitement", "highlight": "behavioriste"}]}, {"id": "communication-concept-042", "chapter": "3 · Les théories", "question": "Que signifie AIDA ?", "answer": "Attention, intérêt, désir, achat.", "sources": [{"documentId": "com", "page": 9, "excerpt": "Modèle AIDA (Lewis, 1898) : Attention → Intérêt → Désir → Achat.\nHiérarchie des effets : un consommateur ne passe pas instantanément de l'ignorance à \nl'achat. 3 niveaux, 6 étapes :\nStade\nÉtape\nDescription\nCognitif Prise de conscience Il découvre l'existence du produit ou de la marque\nConnaissance\nIl acquiert des informations\nAffectif Appréciation\nIl forme une opinion ou un ressenti positif ou négatif\nPréférence", "highlight": "AIDA"}]}, {"id": "communication-concept-043", "chapter": "3 · Les théories", "question": "Quelles sont les six étapes de la hiérarchie des effets ?", "answer": "Prise de conscience, connaissance, appréciation, préférence, conviction et achat.", "sources": [{"documentId": "com", "page": 9, "excerpt": "Cognitif Prise de conscience Il découvre l'existence du produit ou de la marque\nConnaissance\nIl acquiert des informations\nAffectif Appréciation\nIl forme une opinion ou un ressenti positif ou négatif\nPréférence\nIl compare et choisit une marque préférée\nConatif Conviction\nIl est persuadé que c'est le bon choix\nAchat\nIl agit et effectue l'achat\nUtilité : où se situe la cible ? choisir les bons canaux et contenus ; quel message selon l'étape", "highlight": "Prise de conscience"}]}, {"id": "communication-concept-044", "chapter": "3 · Les théories", "question": "Qu’est-ce que le storytelling ?", "answer": "C’est l’art de raconter une histoire pour susciter l’émotion, donner du sens et convaincre.", "sources": [{"documentId": "com", "page": 10, "excerpt": "Art de raconter des histoires à fort pouvoir de séduction et de conviction. Pour parler \nà la tête, il faut souvent d'abord toucher le cœur.\n\nContenu non promotionnel : on crée un environnement, un contexte réel ou fictif lié \nà la marque, au lieu de vanter les points forts du produit. Technique de mise en récit \nsur la base d'une structure.\n\nBut : faire connaître un nouveau produit, améliorer l'image, augmenter la notoriété,", "highlight": "Art de raconter"}]}, {"id": "communication-concept-045", "chapter": "3 · Les théories", "question": "Qu’est-ce que le two-step flow of communication ?", "answer": "C’est une diffusion de la communication en deux temps, dans laquelle les leaders d’opinion jouent un rôle de relais et d’influence.", "sources": [{"documentId": "com", "page": 10, "excerpt": "d'information, rôle d'expert, bâtisseurs de notoriété (e-réputation). Modèle du two-step \nflow of communication.\n5. Analyse sémiotique du message\n\nSémiotique : science générale des signes. Précurseurs : Peirce, de Saussure, R. \nBarthes. Étymologie d'« image » : imitari. L'image est une représentation.\n\nLe signe se décompose en signifiant et signifié. Exemples : montagne (Leroy Merlin)", "highlight": "two-step"}]}, {"id": "communication-concept-046", "chapter": "3 · Les théories", "question": "Qu’est-ce que la sémiotique ?", "answer": "C’est la science générale des signes.", "sources": [{"documentId": "com", "page": 10, "excerpt": "5. Analyse sémiotique du message\n\nSémiotique : science générale des signes. Précurseurs : Peirce, de Saussure, R. \nBarthes. Étymologie d'« image » : imitari. L'image est une représentation.\n\nLe signe se décompose en signifiant et signifié. Exemples : montagne (Leroy Merlin) \n= nature, liberté, air pur ; colombe = amour, espérance, paix.\n\nLa relation signifiant / signifié est implicite ou explicite. Si elle est trop subjective,", "highlight": "sémiotique"}]}, {"id": "communication-concept-047", "chapter": "3 · Les théories", "question": "Quelle différence y a-t-il entre signifiant et signifié ?", "answer": "Le signifiant est la forme perceptible du signe. Le signifié est le sens ou le concept qui lui est associé.", "sources": [{"documentId": "com", "page": 10, "excerpt": "Le signe se décompose en signifiant et signifié. Exemples : montagne (Leroy Merlin) \n= nature, liberté, air pur ; colombe = amour, espérance, paix.\n\nLa relation signifiant / signifié est implicite ou explicite. Si elle est trop subjective, \nrisque de mauvaise interprétation. Un signe peut \nêtre monosémique ou polysémique.\n\nDénotation : le signifié est construit en tant que tel. Connotation : valeur subjective", "highlight": "signifiant"}]}, {"id": "communication-concept-048", "chapter": "3 · Les théories", "question": "Quelle différence y a-t-il entre dénotation et connotation ?", "answer": "La dénotation correspond au sens directement décrit. La connotation renvoie aux significations et valeurs subjectives associées au signe.", "sources": [{"documentId": "com", "page": 10, "excerpt": "Dénotation : le signifié est construit en tant que tel. Connotation : valeur subjective \nliée au signe du fait de sa forme ou fonction.\nCas Pepsi (bad buzz) : signifiés imaginés = unité, rapprochement, paix ; perçu = banalisation \ndes protestations et des violences policières.\nConclusion : plus un signe est polysémique, subjectif et culturellement chargé, \nplus le risque d'interprétation divergente augmente.", "highlight": "Dénotation"}]}, {"id": "communication-concept-049", "chapter": "3 · Les théories", "question": "Qu’est-ce qu’un signe polysémique ?", "answer": "C’est un signe qui peut recevoir plusieurs significations ou interprétations.", "sources": [{"documentId": "com", "page": 10, "excerpt": "être monosémique ou polysémique.\n\nDénotation : le signifié est construit en tant que tel. Connotation : valeur subjective \nliée au signe du fait de sa forme ou fonction.\nCas Pepsi (bad buzz) : signifiés imaginés = unité, rapprochement, paix ; perçu = banalisation \ndes protestations et des violences policières.\nConclusion : plus un signe est polysémique, subjectif et culturellement chargé, \nplus le risque d'interprétation divergente augmente.", "highlight": "polysémique"}]}, {"id": "communication-concept-050", "chapter": "3 · Les théories", "question": "Qu’est-ce qu’une cascade de propagation ?", "answer": "C’est une diffusion dans laquelle chaque personne transmet l’information à plusieurs autres, qui la retransmettent à leur tour.", "sources": [{"documentId": "com", "page": 4, "excerpt": "Cascade de propagation\nElle se produit lorsqu'on donne l'information à plusieurs personnes à la fois et que chacune \nla propage ensuite à plusieurs autres.\nExpériences\n\nGeste\n\nDessin\n\nParole\nÀ retenir : une rumeur se déforme selon les préjugés de ceux qui la relaient.", "highlight": "Cascade"}]}, {"id": "communication-concept-051", "chapter": "3 · Les théories", "question": "Pourquoi une rumeur peut-elle se déformer ?", "answer": "Les préjugés et la culture des personnes qui transmettent l’information peuvent orienter sa sélection, sa transformation et son amplification.", "sources": [{"documentId": "com", "page": 4, "excerpt": "La distorsion de l'information n'est pas aléatoire.\n\nLa déformation reflète nos préjugés et notre culture.\n\nChaque groupe construit la vérité qu'il veut entendre.\nDifférentes chaînes de transmission\nChaîne\nCe qui se passe\nEffet\nInformation transmise à des \npersonnes qui ont déjà des préjugés \nnégatifs\nElle prend de plus en plus \nd'ampleur : tout le monde entend \nl'info et y croit\nMessage de plus en \nplus alarmant\nInformation transmise à des", "highlight": "distorsion"}]}, {"id": "communication-concept-052", "chapter": "4 · Éthique et réglementation", "question": "Quel est le rôle de l’ARPP ?", "answer": "L’Autorité de régulation professionnelle de la publicité participe à l’autorégulation de la publicité et formule des recommandations.", "sources": [{"documentId": "com", "page": 10, "excerpt": "ARPP (Autorité de régulation \nprofessionnelle de la publicité)\nAutorégulation : délivre des recommandations et", "highlight": "ARPP"}]}, {"id": "communication-concept-053", "chapter": "4 · Éthique et réglementation", "question": "Quel est le rôle de l’ARCOM ?", "answer": "Elle régule les médias audiovisuels.", "sources": [{"documentId": "com", "page": 11, "excerpt": "CSA / ARCOM\nRégule les médias audiovisuels\nCNIL\nEncadre la collecte et l'utilisation des données \npersonnelles\nDGCCRF\nLutte contre les pratiques commerciales \ntrompeuses\nEn Europe\n\nDirectives européennes (ex. directive 2005/29/CE sur les pratiques commerciales \ndéloyales).\n\nEncadrement du numérique avec le RGPD (Règlement général sur la protection des \ndonnées, 2018). Ex. : Facebook condamné à plusieurs reprises en Europe pour non-", "highlight": "ARCOM"}]}, {"id": "communication-concept-054", "chapter": "4 · Éthique et réglementation", "question": "Quel est le rôle de la CNIL ?", "answer": "Elle veille à la protection des données personnelles et encadre leur collecte et leur utilisation.", "sources": [{"documentId": "com", "page": 11, "excerpt": "CNIL\nEncadre la collecte et l'utilisation des données \npersonnelles\nDGCCRF\nLutte contre les pratiques commerciales \ntrompeuses\nEn Europe\n\nDirectives européennes (ex. directive 2005/29/CE sur les pratiques commerciales \ndéloyales).\n\nEncadrement du numérique avec le RGPD (Règlement général sur la protection des \ndonnées, 2018). Ex. : Facebook condamné à plusieurs reprises en Europe pour non-\nrespect du RGPD.", "highlight": "CNIL"}]}, {"id": "communication-concept-055", "chapter": "4 · Éthique et réglementation", "question": "Quel est le rôle de la DGCCRF ?", "answer": "Elle lutte notamment contre les pratiques commerciales trompeuses.", "sources": [{"documentId": "com", "page": 11, "excerpt": "DGCCRF\nLutte contre les pratiques commerciales \ntrompeuses\nEn Europe\n\nDirectives européennes (ex. directive 2005/29/CE sur les pratiques commerciales \ndéloyales).\n\nEncadrement du numérique avec le RGPD (Règlement général sur la protection des \ndonnées, 2018). Ex. : Facebook condamné à plusieurs reprises en Europe pour non-\nrespect du RGPD.\n2. Les grandes règles encadrant la publicité\na) Publicité trompeuse ou mensongère", "highlight": "DGCCRF"}]}, {"id": "communication-concept-056", "chapter": "4 · Éthique et réglementation", "question": "Qu’est-ce qu’une publicité trompeuse ?", "answer": "C’est une publicité qui induit le consommateur en erreur, notamment sur le prix, la qualité ou les caractéristiques de l’offre.", "sources": [{"documentId": "com", "page": 11, "excerpt": "trompeuses\nEn Europe\n\nDirectives européennes (ex. directive 2005/29/CE sur les pratiques commerciales \ndéloyales).\n\nEncadrement du numérique avec le RGPD (Règlement général sur la protection des \ndonnées, 2018). Ex. : Facebook condamné à plusieurs reprises en Europe pour non-\nrespect du RGPD.\n2. Les grandes règles encadrant la publicité\na) Publicité trompeuse ou mensongère", "highlight": "trompeuse"}]}, {"id": "communication-concept-057", "chapter": "4 · Éthique et réglementation", "question": "Qu’est-ce qu’une publicité comparative ?", "answer": "C’est une publicité qui identifie explicitement ou implicitement un concurrent ou les biens et services qu’il propose.", "sources": [{"documentId": "com", "page": 11, "excerpt": "b) Publicité comparative\n\nDéfinition : toute publicité qui, explicitement ou implicitement, identifie un \nconcurrent ou les biens / services qu'il offre.\n\nLongtemps non interdite, mais la jurisprudence la rendait impossible. Loi de \n1992 : elle l'autorise si elle est loyale, véridique et permet une comparaison \nvérifiable et objective.\nPOUR\nCONTRE\nS'aligner sur les pays occidentaux\nRelève souvent du dénigrement", "highlight": "comparative"}]}, {"id": "communication-concept-058", "chapter": "4 · Éthique et réglementation", "question": "Que signifie RGPD ?", "answer": "Règlement général sur la protection des données. Il encadre la protection des données personnelles.", "sources": [{"documentId": "com", "page": 11, "excerpt": "Encadrement du numérique avec le RGPD (Règlement général sur la protection des \ndonnées, 2018). Ex. : Facebook condamné à plusieurs reprises en Europe pour non-\nrespect du RGPD.\n2. Les grandes règles encadrant la publicité\na) Publicité trompeuse ou mensongère\nInterdite : ne pas induire le consommateur en erreur (prix, qualité, caractéristiques). Ex. : \npublicité mensongère de Volkswagen sur les émissions polluantes.\nb) Publicité comparative\n", "highlight": "RGPD"}]}, {"id": "communication-concept-059", "chapter": "4 · Éthique et réglementation", "question": "Qu’est-ce que la communication éthique ?", "answer": "C’est une communication responsable qui tient compte de ses effets et respecte les publics auxquels elle s’adresse.", "sources": [{"documentId": "com", "page": 12, "excerpt": "3. L'éthique de la communication commerciale\nSujet\nDéfinition\nExemple\nStéréotypes et \nreprésentation sociale\nRisque de sexisme, \nracisme, grossophobie\nH&M 2018 : enfant noir portant un \nsweat « coolest monkey in the jungle » \n→ accusation de racisme, boycott \nmassif\nGreenwashing / social \nwashing\nPrétendre être écologique \nou engagé sans réelle \naction\nTotalEnergies accusé de greenwashing \ndans ses pubs sur la transition \nénergétique", "highlight": "éthique"}]}, {"id": "communication-concept-060", "chapter": "5 · L’image de marque", "question": "Quelle différence y a-t-il entre identité, image et réputation de marque ?", "answer": "L’identité est ce que la marque veut exprimer. L’image est la représentation que les publics se font d’elle. La réputation se construit dans la durée à partir des opinions et expériences.", "sources": [{"documentId": "com", "page": 13, "excerpt": "Identité de \nmarque\nCe que la marque veut dire d'elle-\nmême : son ADN, sa mission, ses \nvaleurs\nDecathlon : « rendre le sport \naccessible à tous »\nImage de \nmarque\nCe que les consommateurs perçoivent \nréellement : la représentation mentale \nqu'ils s'en font\nTesla veut incarner l'innovation \ndurable, mais certains perçoivent une \nimage liée à Elon Musk\nRéputation\nL'image dans la durée, façonnée par \nl'expérience, le bouche-à-oreille, les \nmédias", "highlight": "Identité de"}]}, {"id": "communication-concept-061", "chapter": "5 · L’image de marque", "question": "Qu’est-ce que la personnalité de marque ?", "answer": "C’est l’ensemble des caractéristiques humaines associées à une marque.", "sources": [{"documentId": "com", "page": 13, "excerpt": "b) Personnalité de marque (Aaker, 1997) : 5 dimensions\nDimension\nTraits associés\nExemples\nSincérité\nHonnêteté, proximité, chaleur, simplicité, \nbienveillance. Marques humaines et \naccessibles, relation de confiance et \nd'authenticité\nDisney (valeurs familiales, magie \nde l'enfance), Innocent\nExcitation\nÉnergie, audace, créativité, modernité, \njeunesse. Marques qui stimulent et \nsurprennent\nRed Bull (sports extrêmes, \ndépassement de soi), TikTok", "highlight": "Personnalité de marque"}]}, {"id": "communication-concept-062", "chapter": "5 · L’image de marque", "question": "Quelles sont les cinq dimensions de la personnalité de marque selon Aaker ?", "answer": "Sincérité, excitation, compétence, sophistication et robustesse.", "sources": [{"documentId": "com", "page": 13, "excerpt": "b) Personnalité de marque (Aaker, 1997) : 5 dimensions\nDimension\nTraits associés\nExemples\nSincérité\nHonnêteté, proximité, chaleur, simplicité, \nbienveillance. Marques humaines et \naccessibles, relation de confiance et \nd'authenticité\nDisney (valeurs familiales, magie \nde l'enfance), Innocent\nExcitation\nÉnergie, audace, créativité, modernité, \njeunesse. Marques qui stimulent et \nsurprennent\nRed Bull (sports extrêmes, \ndépassement de soi), TikTok", "highlight": "Aaker"}]}, {"id": "communication-concept-063", "chapter": "5 · L’image de marque", "question": "Qu’est-ce que le capital marque selon Keller ?", "answer": "C’est la valeur liée à ce que les consommateurs pensent, ressentent et croient au sujet de la marque, au-delà de la qualité réelle du produit.", "sources": [{"documentId": "com", "page": 14, "excerpt": "Le capital-marque (brand equity)\nKeller (1993) : CBBE (Customer Based Brand Equity)\n\nLe pouvoir d'une marque ne dépend pas seulement de sa qualité réelle ou de son \nbudget publicitaire, mais de ce que les consommateurs pensent, ressentent et \ncroient à son sujet.\n\n« Une marque forte se construit dans la tête et le cœur des consommateurs. » Pour \nKeller, l'image de marque est une ressource.\nLa pyramide de Keller, 4 étages :\nÉtage\nDéfinition", "highlight": "capital-marque"}]}, {"id": "communication-concept-064", "chapter": "5 · L’image de marque", "question": "Quels sont les quatre niveaux de la pyramide de Keller ?", "answer": "Notoriété, associations, réponse et résonance.", "sources": [{"documentId": "com", "page": 14, "excerpt": "1. NOTORIÉTÉ\nMarque connue et reconnue. Reconnaissance : « je la reconnais quand je \nla vois ». Rappel spontané : « je la cite sans aide ». Objectif : la marque \nvient naturellement à l'esprit en situation d'achat\n2. \nASSOCIATIONS\nImage mentale de la marque. Associations de \nperformance (fonctionnel : qualité, fiabilité, design, innovation, service ; \nex. Toyota = fiabilité). Associations symboliques /", "highlight": "NOTORIÉTÉ"}]}, {"id": "communication-concept-065", "chapter": "5 · L’image de marque", "question": "Quelles sont les deux grandes catégories d’associations à la marque ?", "answer": "Les associations de performance, liées aux qualités fonctionnelles, et les associations symboliques, liées aux valeurs, au style de vie et à la personnalité.", "sources": [{"documentId": "com", "page": 14, "excerpt": "performance (fonctionnel : qualité, fiabilité, design, innovation, service ; \nex. Toyota = fiabilité). Associations symboliques / \nimaginaires (émotionnel : valeurs, style de vie, personnalité ; ex. Nike = \nperformance et dépassement de soi). C'est ici que se forment les valeurs \net l'univers symbolique\n3. RÉPONSE\nRéactions des consommateurs. Jugement (rationnel : qualité, crédibilité,", "highlight": "performance"}]}, {"id": "communication-concept-066", "chapter": "5 · L’image de marque", "question": "Quelle différence y a-t-il entre jugements et sentiments envers une marque ?", "answer": "Les jugements sont des évaluations rationnelles, notamment de qualité et de crédibilité. Les sentiments sont les réactions affectives suscitées par la marque.", "sources": [{"documentId": "com", "page": 14, "excerpt": "Réactions des consommateurs. Jugement (rationnel : qualité, crédibilité, \nconsidération, supériorité ; ex. Apple jugée innovante et haut de \ngamme). Sentiments (émotionnels : sécurité, plaisir, fierté, excitation, \nnostalgie…)\n4. RÉSONANCE\nRelation forte, durable et affective. Fidélité comportementale (achats \nrépétés), attachement affectif(« la marque fait partie de moi \n»), sentiment d'appartenance (communauté forte), engagement", "highlight": "Jugement"}]}, {"id": "communication-concept-067", "chapter": "5 · L’image de marque", "question": "Qu’est-ce que la résonance de marque ?", "answer": "C’est une relation forte et durable avec la marque, qui combine fidélité comportementale, attachement affectif, appartenance et engagement actif.", "sources": [{"documentId": "com", "page": 14, "excerpt": "4. RÉSONANCE\nRelation forte, durable et affective. Fidélité comportementale (achats \nrépétés), attachement affectif(« la marque fait partie de moi \n»), sentiment d'appartenance (communauté forte), engagement \nactif(ambassadeurs). Ex. : clubs et tatouages Harley-Davidson, fans \nd'Apple qui font la queue\nUtilité du modèle : diagnostiquer à quel niveau se situe la marque et planifier des actions \nadaptées à chaque étape :\n1. Campagne de notoriété", "highlight": "RÉSONANCE"}]}, {"id": "communication-concept-068", "chapter": "5 · L’image de marque", "question": "Qu’est-ce que la dissonance entre identité et image de marque ?", "answer": "C’est un décalage entre ce que la marque veut exprimer et la façon dont elle est réellement perçue.", "sources": [{"documentId": "com", "page": 15, "excerpt": "Dissonance\nDécalage entre \nidentité voulue et \nimage perçue\nMcDonald's veut se \nrepositionner sur une image \nplus équilibrée et moderne, \nmais reste perçu comme fast-\nfood gras, industriel, riche en \nsucre et en sel → tentative \nperçue comme superficielle \nvoire hypocrite\nUne marque ne peut pas \nchanger son \nimage uniquement par \nla communication : il \nfaut changer les 4P pour \nêtre cohérent\nBad buzz\nErreur de \ncommunication \nvirale", "highlight": "Dissonance"}]}, {"id": "communication-concept-069", "chapter": "5 · L’image de marque", "question": "Qu’est-ce qu’un bad buzz ?", "answer": "C’est la propagation rapide de réactions négatives qui peut dégrader l’image et la réputation d’une marque.", "sources": [{"documentId": "com", "page": 15, "excerpt": "Bad buzz\nErreur de \ncommunication \nvirale\nMarque italienne, 2018 : vidéos \nInstagram d'une Chinoise \nmangeant un plat italien avec \ndes baguettes. Intention : \nhumour sur le choc culturel. \nRéception : racisme, \ncondescendance, stéréotypes. \nConséquences : boycott, \nannulation du défilé, excuses \ntardives jugées peu sincères\nComprendre les \ndifférences culturelles \navant de communiquer, \nsurtout à l'ère des réseaux \nsociaux\nGreenwashing /", "highlight": "Bad buzz"}]}, {"id": "communication-concept-070", "chapter": "5 · L’image de marque", "question": "Qu’est-ce que le greenwashing ou le social washing ?", "answer": "C’est le fait de revendiquer des engagements environnementaux ou sociaux peu sincères, trompeurs ou insuffisamment soutenus par les pratiques réelles.", "sources": [{"documentId": "com", "page": 15, "excerpt": "Greenwashing / \nsocial washing\nCommuniquer sur \ndes valeurs \néthiques sans les \nappliquer\nH&M et la « Conscious \ncollection » : gamme censée \nêtre durable, étiquettes \nécologiques trompeuses → \nbaisse de crédibilité\nActions réelles et \nmesurables\nLe partiel : informations pratiques\n\nNe pas être en retard ; rentrer par le bas.\n\nDurée : 1h30.\n\nQuelques questions de cours. Pas besoin de définitions apprises par cœur, tant que la", "highlight": "washing"}]}], "documents": ["com"]}];
